/* @rottay/design-system - bithire vertical bundle */
/* Generated by build-vertical-css.mjs */
/* Structure: base tokens + modern engine + bithire tenant (unlayered, wins by specificity) */

/**
 * Rottay Design System - Tenant-free base CSS
 *
 * Contains everything from index.css EXCEPT tenant overrides (Layer 4).
 * Used by build-vertical-css.mjs to create per-vertical dist bundles
 * that include only one tenant's CSS.
 *
 * Layers included:
 * - 0: antd reset
 * - 1: DS foundation + default theme
 * - 2: Component tokens
 * - 3: Engine themes (classic, modern, rustic)
 * - 5: Personality overrides
 * - 6: Responsive overrides
 * - Accessibility + Animations (unlayered)
 *
 * Layer 4 (tenant overrides) is intentionally omitted.
 * Each vertical CSS adds its own tenant import.
 *
 * @version 1.0.0
 */

/* Layer order declaration */
@layer rottay-reset, rottay-tokens, rottay-components, rottay-engines, rottay-tenants, rottay-personality, rottay-responsive;

/* Layer 0: antd reset */
@import 'antd/dist/reset.css' layer(rottay-reset);

/* Layer 1: DS foundation + default theme */
@layer rottay-tokens {
/**
 * Base Tokens Index - Rottay Design System
 *
 * Supplemental semantic token layer for the DS-prefixed runtime.
 * Import this file to get the extended spacing, border, shadow, typography,
 * and z-index aliases that sit on top of the canonical theme palettes.
 */

/**
 * Base Spacing Tokens - Rottay Design System
 *
 * Spacing scale based on 4px grid for consistency.
 * All spacing values are multiples of 4px.
 */

:root {
  /* ========================================================================
     SPACING SCALE - 4px Grid System
     Used for margins, paddings, gaps, and any dimensional spacing
     ======================================================================== */
  --ds-spacing-0: 0;
  --ds-spacing-1: 0.25rem;   /* 4px */
  --ds-spacing-2: 0.5rem;    /* 8px */
  --ds-spacing-3: 0.75rem;   /* 12px */
  --ds-spacing-4: 1rem;      /* 16px */
  --ds-spacing-5: 1.25rem;   /* 20px */
  --ds-spacing-6: 1.5rem;    /* 24px */
  --ds-spacing-7: 1.75rem;   /* 28px */
  --ds-spacing-8: 2rem;      /* 32px */
  --ds-spacing-9: 2.25rem;   /* 36px */
  --ds-spacing-10: 2.5rem;   /* 40px */
  --ds-spacing-11: 2.75rem;  /* 44px */
  --ds-spacing-12: 3rem;     /* 48px */
  --ds-spacing-14: 3.5rem;   /* 56px */
  --ds-spacing-16: 4rem;     /* 64px */
  --ds-spacing-20: 5rem;     /* 80px */
  --ds-spacing-24: 6rem;     /* 96px */
  --ds-spacing-28: 7rem;     /* 112px */
  --ds-spacing-32: 8rem;     /* 128px */
  --ds-spacing-36: 9rem;     /* 144px */
  --ds-spacing-40: 10rem;    /* 160px */
  --ds-spacing-44: 11rem;    /* 176px */
  --ds-spacing-48: 12rem;    /* 192px */
  --ds-spacing-52: 13rem;    /* 208px */
  --ds-spacing-56: 14rem;    /* 224px */
  --ds-spacing-60: 15rem;    /* 240px */
  --ds-spacing-64: 16rem;    /* 256px */
  --ds-spacing-72: 18rem;    /* 288px */
  --ds-spacing-80: 20rem;    /* 320px */
  --ds-spacing-96: 24rem;    /* 384px */

  /* ========================================================================
     NAMED SPACING - Semantic Aliases
     Commonly used spacing values with semantic names
     ======================================================================== */
  --ds-spacing-xxxs: var(--ds-spacing-1);   /* 4px */
  --ds-spacing-xxs: var(--ds-spacing-2);    /* 8px */
  --ds-spacing-xs: var(--ds-spacing-3);     /* 12px */
  --ds-spacing-sm: var(--ds-spacing-4);     /* 16px */
  --ds-spacing-md: var(--ds-spacing-6);     /* 24px */
  --ds-spacing-lg: var(--ds-spacing-8);     /* 32px */
  --ds-spacing-xl: var(--ds-spacing-10);    /* 40px */
  --ds-spacing-2xl: var(--ds-spacing-12);   /* 48px */
  --ds-spacing-3xl: var(--ds-spacing-16);   /* 64px */
  --ds-spacing-4xl: var(--ds-spacing-20);   /* 80px */
  --ds-spacing-5xl: var(--ds-spacing-24);   /* 96px */

  /* ========================================================================
     LAYOUT SPACING - Page/Section Level
     Used for larger layout spacing needs
     ======================================================================== */
  --ds-spacing-gutter: var(--ds-spacing-4);        /* 16px - Base gutter */
  --ds-spacing-gutter-sm: var(--ds-spacing-2);     /* 8px - Small screens */
  --ds-spacing-gutter-md: var(--ds-spacing-6);     /* 24px - Medium screens */
  --ds-spacing-gutter-lg: var(--ds-spacing-8);     /* 32px - Large screens */
  --ds-spacing-gutter-xl: var(--ds-spacing-12);    /* 48px - Extra large screens */

  --ds-spacing-section: var(--ds-spacing-16);      /* 64px - Section spacing */
  --ds-spacing-section-sm: var(--ds-spacing-8);    /* 32px - Small sections */
  --ds-spacing-section-lg: var(--ds-spacing-24);   /* 96px - Large sections */

  --ds-spacing-container: var(--ds-spacing-6);     /* 24px - Container padding */
  --ds-spacing-container-sm: var(--ds-spacing-4);  /* 16px - Small containers */
  --ds-spacing-container-lg: var(--ds-spacing-12); /* 48px - Large containers */

  /* ========================================================================
     COMPONENT SPACING - Component-Specific
     Default spacing for common component patterns
     ======================================================================== */
  --ds-spacing-component-gap: var(--ds-spacing-4);          /* 16px - Gap between items */
  --ds-spacing-component-gap-sm: var(--ds-spacing-2);       /* 8px - Small gap */
  --ds-spacing-component-gap-lg: var(--ds-spacing-6);       /* 24px - Large gap */

  --ds-spacing-component-padding: var(--ds-spacing-4);      /* 16px - Internal padding */
  --ds-spacing-component-padding-sm: var(--ds-spacing-2);   /* 8px - Small padding */
  --ds-spacing-component-padding-lg: var(--ds-spacing-6);   /* 24px - Large padding */

  --ds-spacing-component-margin: var(--ds-spacing-4);       /* 16px - External margin */
  --ds-spacing-component-margin-sm: var(--ds-spacing-2);    /* 8px - Small margin */
  --ds-spacing-component-margin-lg: var(--ds-spacing-8);    /* 32px - Large margin */

  /* ---------------------------------------------------------------------
   * Fluid space ramp (WO-ARC-05).
   *
   * `--ds-space-fluid-N` runs from `--ds-spacing-N` to the NEXT step the static
   * ramp defines -- so `--ds-space-fluid-12` ends at `--ds-spacing-14`, because
   * 13 does not exist. Interpolated in `cqi` between 360px and 1280px, hitting
   * both bounds exactly. Opt-in; nothing consumes these by default.
   * ------------------------------------------------------------------------ */
  --ds-space-fluid-1: clamp(0.25rem, 0.1522rem + 0.4348cqi, 0.5rem);
  --ds-space-fluid-2: clamp(0.5rem, 0.4022rem + 0.4348cqi, 0.75rem);
  --ds-space-fluid-3: clamp(0.75rem, 0.6522rem + 0.4348cqi, 1rem);
  --ds-space-fluid-4: clamp(1rem, 0.9022rem + 0.4348cqi, 1.25rem);
  --ds-space-fluid-6: clamp(1.5rem, 1.4022rem + 0.4348cqi, 1.75rem);
  --ds-space-fluid-8: clamp(2rem, 1.9022rem + 0.4348cqi, 2.25rem);
  --ds-space-fluid-10: clamp(2.5rem, 2.4022rem + 0.4348cqi, 2.75rem);
  --ds-space-fluid-12: clamp(3rem, 2.8043rem + 0.8696cqi, 3.5rem);
}

/**
 * Base Typography Tokens - Rottay Design System
 *
 * Typography scale including font families, sizes, weights, line heights,
 * and letter spacing for consistent text styling across the system.
 */

:root {
  /* ========================================================================
     FONT FAMILIES
     Define the typeface stacks for different text purposes
     ======================================================================== */
  --ds-font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
                      'Helvetica Neue', Arial, 'Noto Sans', sans-serif,
                      'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol',
                      'Noto Color Emoji';
  --ds-font-family-heading: var(--ds-font-family-base);
  --ds-font-family-mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Monaco,
                      Consolas, 'Liberation Mono', 'Courier New', monospace;
  --ds-font-family-display: var(--ds-font-family-base);

  /* ========================================================================
     FONT SIZES
     Type scale from small to 4xl for consistent text sizing
     ======================================================================== */
  --ds-font-size-xs: 0.75rem;      /* 12px */
  --ds-font-size-sm: 0.875rem;     /* 14px */
  --ds-font-size-base: 1rem;       /* 16px - Base font size */
  --ds-font-size-md: 1rem;         /* 16px - Alias for base */
  --ds-font-size-lg: 1.125rem;     /* 18px */
  --ds-font-size-xl: 1.25rem;      /* 20px */
  --ds-font-size-2xl: 1.5rem;      /* 24px */
  --ds-font-size-3xl: 1.875rem;    /* 30px */
  --ds-font-size-4xl: 2.25rem;     /* 36px */
  --ds-font-size-5xl: 3rem;        /* 48px */
  --ds-font-size-6xl: 3.75rem;     /* 60px */
  --ds-font-size-7xl: 4.5rem;      /* 72px */
  --ds-font-size-8xl: 6rem;        /* 96px */
  --ds-font-size-9xl: 8rem;        /* 128px */

  /* ========================================================================
     HEADING SIZES
     Predefined sizes for heading elements
     ======================================================================== */
  --ds-font-size-h1: var(--ds-font-size-4xl);   /* 36px */
  --ds-font-size-h2: var(--ds-font-size-3xl);   /* 30px */
  --ds-font-size-h3: var(--ds-font-size-2xl);   /* 24px */
  --ds-font-size-h4: var(--ds-font-size-xl);    /* 20px */
  --ds-font-size-h5: var(--ds-font-size-lg);    /* 18px */
  --ds-font-size-h6: var(--ds-font-size-base);  /* 16px */

  /* ========================================================================
     FONT WEIGHTS
     Weight scale for text emphasis
     ======================================================================== */
  --ds-font-weight-thin: 100;
  --ds-font-weight-extralight: 200;
  --ds-font-weight-light: 300;
  --ds-font-weight-normal: 400;
  --ds-font-weight-medium: 500;
  --ds-font-weight-semibold: 600;
  --ds-font-weight-bold: 700;
  --ds-font-weight-extrabold: 800;
  --ds-font-weight-black: 900;

  /* Semantic aliases */
  --ds-font-weight-body: var(--ds-font-weight-normal);
  --ds-font-weight-heading: var(--ds-font-weight-semibold);
  --ds-font-weight-display: var(--ds-font-weight-bold);

  /* ========================================================================
     LINE HEIGHTS
     Vertical spacing for text readability
     ======================================================================== */
  --ds-line-height-none: 1;
  --ds-line-height-tight: 1.25;
  --ds-line-height-snug: 1.375;
  --ds-line-height-normal: 1.5;
  --ds-line-height-relaxed: 1.625;
  --ds-line-height-loose: 2;

  /* Contextual line heights */
  --ds-line-height-body: 1.6;                               /* Relaxed for readability */
  --ds-line-height-heading: 1.2;                            /* Tight for premium headings */
  --ds-line-height-label: 1.4;                              /* Balanced for labels/metadata */
  --ds-line-height-display: var(--ds-line-height-none);     /* 1 */

  /* ========================================================================
     LETTER SPACING
     Horizontal spacing between characters
     ======================================================================== */
  --ds-letter-spacing-tighter: -0.05em;
  --ds-letter-spacing-tight: -0.025em;
  --ds-letter-spacing-snug: -0.015em;
  --ds-letter-spacing-subtle: -0.01em;
  --ds-letter-spacing-normal: 0;
  --ds-letter-spacing-subtle-wide: 0.01em;
  --ds-letter-spacing-wide: 0.025em;
  --ds-letter-spacing-wider: 0.05em;
  --ds-letter-spacing-widest: 0.1em;

  /* Heading-specific tracking: larger sizes get tighter spacing
     for the editorial, premium feel (Linear / Vercel / Stripe). */
  --ds-letter-spacing-h1: -0.025em;
  --ds-letter-spacing-h2: -0.02em;
  --ds-letter-spacing-h3: -0.015em;
  --ds-letter-spacing-h4: -0.01em;
  --ds-letter-spacing-h5: 0;
  --ds-letter-spacing-h6: 0;

  /* ========================================================================
     TEXT TRANSFORM
     Common text transformations
     ======================================================================== */
  --ds-text-transform-none: none;
  --ds-text-transform-uppercase: uppercase;
  --ds-text-transform-lowercase: lowercase;
  --ds-text-transform-capitalize: capitalize;

  /* ========================================================================
     TEXT DECORATION
     Common text decorations
     ======================================================================== */
  --ds-text-decoration-none: none;
  --ds-text-decoration-underline: underline;
  --ds-text-decoration-line-through: line-through;

  /* ========================================================================
     COMPOSITE TEXT STYLES
     Pre-composed text styles for common use cases
     ======================================================================== */

  /* Display styles */
  --ds-text-display-1-size: var(--ds-font-size-6xl);
  --ds-text-display-1-weight: var(--ds-font-weight-bold);
  --ds-text-display-1-line-height: var(--ds-line-height-none);
  --ds-text-display-1-letter-spacing: var(--ds-letter-spacing-tight);

  --ds-text-display-2-size: var(--ds-font-size-5xl);
  --ds-text-display-2-weight: var(--ds-font-weight-bold);
  --ds-text-display-2-line-height: var(--ds-line-height-none);
  --ds-text-display-2-letter-spacing: var(--ds-letter-spacing-tight);

  /* Heading styles - Premium typography with tighter tracking at larger sizes */
  --ds-text-heading-1-size: var(--ds-font-size-h1);
  --ds-text-heading-1-weight: var(--ds-font-weight-bold);
  --ds-text-heading-1-line-height: 1.1;
  --ds-text-heading-1-letter-spacing: var(--ds-letter-spacing-h1);

  --ds-text-heading-2-size: var(--ds-font-size-h2);
  --ds-text-heading-2-weight: var(--ds-font-weight-bold);
  --ds-text-heading-2-line-height: 1.15;
  --ds-text-heading-2-letter-spacing: var(--ds-letter-spacing-h2);

  --ds-text-heading-3-size: var(--ds-font-size-h3);
  --ds-text-heading-3-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-3-line-height: 1.2;
  --ds-text-heading-3-letter-spacing: var(--ds-letter-spacing-h3);

  --ds-text-heading-4-size: var(--ds-font-size-h4);
  --ds-text-heading-4-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-4-line-height: 1.25;
  --ds-text-heading-4-letter-spacing: var(--ds-letter-spacing-h4);

  --ds-text-heading-5-size: var(--ds-font-size-h5);
  --ds-text-heading-5-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-5-line-height: 1.3;
  --ds-text-heading-5-letter-spacing: var(--ds-letter-spacing-h5);

  --ds-text-heading-6-size: var(--ds-font-size-h6);
  --ds-text-heading-6-weight: var(--ds-font-weight-semibold);
  --ds-text-heading-6-line-height: 1.4;
  --ds-text-heading-6-letter-spacing: var(--ds-letter-spacing-h6);

  /* Body styles */
  --ds-text-body-lg-size: var(--ds-font-size-lg);
  --ds-text-body-lg-weight: var(--ds-font-weight-normal);
  --ds-text-body-lg-line-height: var(--ds-line-height-normal);

  --ds-text-body-md-size: var(--ds-font-size-base);
  --ds-text-body-md-weight: var(--ds-font-weight-normal);
  --ds-text-body-md-line-height: var(--ds-line-height-normal);

  --ds-text-body-sm-size: var(--ds-font-size-sm);
  --ds-text-body-sm-weight: var(--ds-font-weight-normal);
  --ds-text-body-sm-line-height: var(--ds-line-height-normal);

  --ds-text-body-xs-size: var(--ds-font-size-xs);
  --ds-text-body-xs-weight: var(--ds-font-weight-normal);
  --ds-text-body-xs-line-height: var(--ds-line-height-normal);

  /* Caption styles */
  --ds-text-caption-size: var(--ds-font-size-sm);
  --ds-text-caption-weight: var(--ds-font-weight-normal);
  --ds-text-caption-line-height: var(--ds-line-height-snug);
  --ds-text-caption-color: var(--ds-color-neutral-600);

  /* Label styles */
  --ds-text-label-size: var(--ds-font-size-sm);
  --ds-text-label-weight: var(--ds-font-weight-medium);
  --ds-text-label-line-height: var(--ds-line-height-normal);
  --ds-text-label-letter-spacing: var(--ds-letter-spacing-wide);

  /* Code/Mono styles */
  --ds-text-code-size: var(--ds-font-size-sm);
  --ds-text-code-weight: var(--ds-font-weight-normal);
  --ds-text-code-line-height: var(--ds-line-height-normal);
  --ds-text-code-family: var(--ds-font-family-mono);

  /* ========================================================================
     MICRO-TYPOGRAPHY (WO-CRA-01)
     Numeric alignment, line wrapping, and optical sizing. The utility classes
     below and the TS mirror (tokens/ts/base/typography.ts) consume these so no
     consumer re-invents the values inline.
     ======================================================================== */
  --ds-numeric-tabular: tabular-nums;
  --ds-numeric-proportional: proportional-nums;
  --ds-font-feature-tabular: "tnum" 1, "lnum" 1;
  --ds-text-wrap-balance: balance;
  --ds-text-wrap-pretty: pretty;
  --ds-hyphens-auto: auto;

  /* ---------------------------------------------------------------------
   * Fluid type ramp (WO-ARC-05).
   *
   * Each fluid step is bounded by two ADJACENT static steps above -- no new
   * magnitudes enter the system, only the path between two that already exist.
   * The ramp interpolates linearly between 360px and 1280px, the same widths
   * the WO-ENG-12 capture law photographs, and hits each bound exactly there.
   *
   * The interpolation unit is `cqi`, not `vw`: a design system renders the same
   * component at rail width, half width and full width inside one viewport, and
   * a viewport unit cannot tell those apart. Where no ancestor declares
   * `container-type`, `cqi` resolves against the small viewport, which is the
   * behaviour a `vw` ramp would have had.
   *
   * Opt-in. Nothing consumes these by default; a skin or surface reaches for one
   * where a static step is cramped at 360px or oversized at 1280px.
   * ------------------------------------------------------------------------ */
  --ds-font-size-fluid-sm: clamp(0.75rem, 0.7011rem + 0.2174cqi, 0.875rem);
  --ds-font-size-fluid-base: clamp(0.875rem, 0.8261rem + 0.2174cqi, 1rem);
  --ds-font-size-fluid-lg: clamp(1rem, 0.9511rem + 0.2174cqi, 1.125rem);
  --ds-font-size-fluid-xl: clamp(1.125rem, 1.0761rem + 0.2174cqi, 1.25rem);
  --ds-font-size-fluid-2xl: clamp(1.25rem, 1.1522rem + 0.4348cqi, 1.5rem);
  --ds-font-size-fluid-3xl: clamp(1.5rem, 1.3533rem + 0.6522cqi, 1.875rem);
  --ds-font-size-fluid-4xl: clamp(1.875rem, 1.7283rem + 0.6522cqi, 2.25rem);
  --ds-font-size-fluid-5xl: clamp(2.25rem, 1.9565rem + 1.3043cqi, 3rem);
}

/* ==========================================================================
   MICRO-TYPOGRAPHY UTILITIES (WO-CRA-01)
   Opt-in classes so data surfaces align digits and prose wraps cleanly. Every
   property degrades gracefully — it is ignored, never broken, where the engine
   or font lacks support.
   ========================================================================== */

/* Optical sizing: tenant variable/optical fonts render at their designed
   optical size. Harmless on fonts without an optical axis. :where() keeps the
   specificity at 0 so apps and tenants can still override. */
:where(html) {
  font-optical-sizing: auto;
}

/* Tabular (fixed-advance) figures so numbers align column-to-column in tables
   and metric tiles instead of jittering with proportional digits. */
.ds-nums-tabular {
  font-variant-numeric: tabular-nums;
  font-feature-settings: var(--ds-font-feature-tabular);
}

/* Balanced multi-line headings — even line lengths, no lonely last word. */
.ds-text-balance {
  text-wrap: balance;
}

/* Prettier body wrapping — avoids a single-word final line (orphan). */
.ds-text-pretty {
  text-wrap: pretty;
}

/* Automatic hyphenation for narrow measures (honors the element's lang). */
.ds-hyphenate {
  hyphens: auto;
}

/**
 * Base Shadow Tokens - Rottay Design System
 *
 * Shadow scale for depth and elevation in the UI.
 * Includes box shadows and drop shadows for consistent layering.
 */

:root {
  /* ========================================================================
     BOX SHADOWS - aliases of the --ds-elevation-0..5 depth scale
     --ds-elevation-* is defined in themes/default.css (co-loaded with this file
     in every entrypoint). classic/rustic components and the brand compiler
     consume these --ds-shadow-* names.
     ======================================================================== */
  --ds-shadow-none: var(--ds-elevation-0);
  --ds-shadow-xs: var(--ds-elevation-1);
  --ds-shadow-sm: var(--ds-elevation-1);
  --ds-shadow-md: var(--ds-elevation-2);
  --ds-shadow-lg: var(--ds-elevation-3);
  --ds-shadow-xl: var(--ds-elevation-4);
  --ds-shadow-2xl: var(--ds-elevation-5);
  --ds-shadow-3xl: var(--ds-elevation-5), 0 48px 96px rgba(0, 0, 0, 0.1);

  /* Inner shadow for inset effects */
  --ds-shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.05);

  /* ========================================================================
     COLORED SHADOWS - Brand/Semantic Shadows
     Shadows with color tints for special emphasis
     ======================================================================== */

  /* Primary shadows */
  --ds-shadow-primary-sm: 0 1px 3px 0 rgba(0, 102, 204, 0.12),
                       0 1px 2px -1px rgba(0, 102, 204, 0.12);

  --ds-shadow-primary-md: 0 4px 6px -1px rgba(0, 102, 204, 0.12),
                       0 2px 4px -2px rgba(0, 102, 204, 0.12);

  --ds-shadow-primary-lg: 0 10px 15px -3px rgba(0, 102, 204, 0.15),
                       0 4px 6px -4px rgba(0, 102, 204, 0.15);

  /* Secondary shadows */
  --ds-shadow-secondary-sm: 0 1px 3px 0 rgba(107, 107, 212, 0.12),
                         0 1px 2px -1px rgba(107, 107, 212, 0.12);

  --ds-shadow-secondary-md: 0 4px 6px -1px rgba(107, 107, 212, 0.12),
                         0 2px 4px -2px rgba(107, 107, 212, 0.12);

  /* Success shadows */
  --ds-shadow-success-sm: 0 1px 3px 0 rgba(34, 197, 94, 0.12),
                       0 1px 2px -1px rgba(34, 197, 94, 0.12);

  --ds-shadow-success-md: 0 4px 6px -1px rgba(34, 197, 94, 0.12),
                       0 2px 4px -2px rgba(34, 197, 94, 0.12);

  /* Warning shadows */
  --ds-shadow-warning-sm: 0 1px 3px 0 rgba(245, 158, 11, 0.12),
                       0 1px 2px -1px rgba(245, 158, 11, 0.12);

  --ds-shadow-warning-md: 0 4px 6px -1px rgba(245, 158, 11, 0.12),
                       0 2px 4px -2px rgba(245, 158, 11, 0.12);

  /* Error shadows */
  --ds-shadow-error-sm: 0 1px 3px 0 rgba(239, 68, 68, 0.12),
                     0 1px 2px -1px rgba(239, 68, 68, 0.12);

  --ds-shadow-error-md: 0 4px 6px -1px rgba(239, 68, 68, 0.12),
                     0 2px 4px -2px rgba(239, 68, 68, 0.12);

  /* ========================================================================
     DROP SHADOWS - CSS Filter Shadows
     Used with the filter property for images and elements
     ======================================================================== */
  --ds-drop-shadow-none: drop-shadow(0 0 0 rgba(0, 0, 0, 0));
  --ds-drop-shadow-xs: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.05));
  --ds-drop-shadow-sm: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.1));
  --ds-drop-shadow-md: drop-shadow(0 4px 3px rgba(0, 0, 0, 0.07))
                    drop-shadow(0 2px 2px rgba(0, 0, 0, 0.06));
  --ds-drop-shadow-lg: drop-shadow(0 10px 8px rgba(0, 0, 0, 0.04))
                    drop-shadow(0 4px 3px rgba(0, 0, 0, 0.1));
  --ds-drop-shadow-xl: drop-shadow(0 20px 13px rgba(0, 0, 0, 0.03))
                    drop-shadow(0 8px 5px rgba(0, 0, 0, 0.08));
  --ds-drop-shadow-2xl: drop-shadow(0 25px 25px rgba(0, 0, 0, 0.15));

  /* ========================================================================
     COMPONENT SHADOWS - Specific Component Elevations
     Predefined shadows for common component states
     ======================================================================== */

  /* Card shadows */
  --ds-shadow-card-rest: var(--ds-shadow-sm);
  --ds-shadow-card-hover: var(--ds-shadow-md);
  --ds-shadow-card-active: var(--ds-shadow-xs);

  /* Button shadows */
  --ds-shadow-button-rest: var(--ds-shadow-xs);
  --ds-shadow-button-hover: var(--ds-shadow-sm);
  --ds-shadow-button-active: var(--ds-shadow-none);

  /* Modal/Dialog shadows */
  --ds-shadow-modal: var(--ds-shadow-2xl);
  --ds-shadow-dialog: var(--ds-shadow-xl);

  /* Dropdown/Menu shadows */
  --ds-shadow-dropdown: var(--ds-shadow-lg);
  --ds-shadow-menu: var(--ds-shadow-lg);

  /* Popover/Tooltip shadows */
  --ds-shadow-popover: var(--ds-shadow-md);
  --ds-shadow-tooltip: var(--ds-shadow-sm);

  /* Drawer shadows */
  --ds-shadow-drawer: var(--ds-shadow-xl);

  /* Navigation shadows */
  --ds-shadow-navbar: var(--ds-shadow-sm);
  --ds-shadow-sidebar: var(--ds-shadow-md);

  /* Input shadows */
  --ds-shadow-input-rest: var(--ds-shadow-none);
  --ds-shadow-input-focus: 0 0 0 3px var(--ds-color-alpha-primary-10, rgba(0, 102, 204, 0.1));
  --ds-shadow-input-error: 0 0 0 3px var(--ds-color-alpha-error-10, rgba(239, 68, 68, 0.1));

  /* ========================================================================
     FOCUS RING SHADOWS
     Accessibility-focused outlines for keyboard navigation
     ======================================================================== */
  --ds-shadow-focus-ring: 0 0 0 3px var(--ds-color-alpha-primary-20, rgba(0, 102, 204, 0.2));
  --ds-shadow-focus-ring-error: 0 0 0 3px var(--ds-color-alpha-error-20, rgba(239, 68, 68, 0.2));
  --ds-shadow-focus-ring-success: 0 0 0 3px var(--ds-color-alpha-success-20, rgba(34, 197, 94, 0.2));
  --ds-shadow-focus-ring-warning: 0 0 0 3px var(--ds-color-alpha-warning-20, rgba(245, 158, 11, 0.2));
}

/**
 * Base Border Tokens - Rottay Design System
 *
 * Border widths, radii, and styles for consistent component boundaries.
 */

:root {
  /* ========================================================================
     BORDER WIDTHS
     Standard border widths for component boundaries
     ======================================================================== */
  --ds-border-width-0: 0;
  --ds-border-width-1: 1px;
  --ds-border-width-2: 2px;
  --ds-border-width-4: 4px;
  --ds-border-width-8: 8px;

  /* Semantic aliases */
  --ds-border-width-none: var(--ds-border-width-0);
  --ds-border-width-thin: var(--ds-border-width-1);
  --ds-border-width-default: var(--ds-border-width-1);
  --ds-border-width-medium: var(--ds-border-width-2);
  --ds-border-width-thick: var(--ds-border-width-4);

  /* ========================================================================
     BORDER RADIUS - Rounding Scale
     Consistent corner rounding for components
     ======================================================================== */

  /* Component-specific radius */
  --ds-radius-button: var(--ds-radius-md);
  --ds-radius-input: var(--ds-radius-md);
  --ds-radius-card: var(--ds-radius-lg);
  --ds-radius-modal: var(--ds-radius-xl);
  --ds-radius-badge: var(--ds-radius-full);
  --ds-radius-avatar: var(--ds-radius-full);

  /* ========================================================================
     BORDER STYLES
     Line styles for borders
     ======================================================================== */
  --ds-border-style-none: none;
  --ds-border-style-solid: solid;
  --ds-border-style-dashed: dashed;
  --ds-border-style-dotted: dotted;
  --ds-border-style-double: double;

  /* ========================================================================
     BORDER COLORS
     Contextual border colors based on the color palette
     ======================================================================== */

  /* Default borders */
  --ds-border-color-default: var(--ds-color-neutral-200);
  --ds-border-color-muted: var(--ds-color-neutral-100);
  --ds-border-color-strong: var(--ds-color-neutral-300);

  /* Interactive borders */
  --ds-border-color-hover: var(--ds-color-neutral-300);
  --ds-border-color-focus: var(--ds-color-primary-500);
  --ds-border-color-active: var(--ds-color-primary-600);

  /* Semantic borders */
  --ds-border-color-primary: var(--ds-color-primary-500);
  --ds-border-color-secondary: var(--ds-color-secondary-500);
  --ds-border-color-success: var(--ds-color-success-500);
  --ds-border-color-warning: var(--ds-color-warning-500);
  --ds-border-color-error: var(--ds-color-error-500);
  --ds-border-color-info: var(--ds-color-info-500);

  /* Transparent borders for spacing */
  --ds-border-color-transparent: transparent;

  /* ========================================================================
     DIVIDER STYLES
     Styles for visual separators
     ======================================================================== */
  --ds-divider-width: var(--ds-border-width-1);
  --ds-divider-color: var(--ds-border-color-default);
  --ds-divider-style: var(--ds-border-style-solid);

  /* Divider with spacing */
  --ds-divider-spacing-sm: var(--ds-spacing-2);   /* 8px */
  --ds-divider-spacing-md: var(--ds-spacing-4);   /* 16px */
  --ds-divider-spacing-lg: var(--ds-spacing-6);   /* 24px */

  /* ========================================================================
     OUTLINE STYLES
     Styles for focus outlines and accessibility
     ======================================================================== */
  --ds-outline-width: 2px;
  --ds-outline-offset: 2px;
  --ds-outline-style: solid;
  --ds-outline-color-default: var(--ds-color-primary-500);
  --ds-outline-color-error: var(--ds-color-error-500);

  /* ========================================================================
     COMPOSITE BORDERS
     Pre-composed border combinations for common use cases
     ======================================================================== */

  /* Default component borders */
  --ds-border-default: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-default);
  --ds-border-muted: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-muted);
  --ds-border-strong: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-strong);

  /* Interactive borders */
  --ds-border-hover: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-hover);
  --ds-border-focus: var(--ds-border-width-2) var(--ds-border-style-solid) var(--ds-border-color-focus);

  /* Semantic borders */
  --ds-border-primary: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-primary);
  --ds-border-secondary: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-secondary);
  --ds-border-success: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-success);
  --ds-border-warning: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-warning);
  --ds-border-error: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-error);
  --ds-border-info: var(--ds-border-width-1) var(--ds-border-style-solid) var(--ds-border-color-info);

  /* Dashed borders */
  --ds-border-dashed: var(--ds-border-width-1) var(--ds-border-style-dashed) var(--ds-border-color-default);
  --ds-border-dashed-muted: var(--ds-border-width-1) var(--ds-border-style-dashed) var(--ds-border-color-muted);

  /* Transparent placeholder borders (for maintaining layout) */
  --ds-border-transparent: var(--ds-border-width-1) var(--ds-border-style-solid) transparent;
}

/**
 * Base Z-Index Tokens - Rottay Design System
 *
 * Z-index layering system for consistent element stacking.
 * Uses a scale that leaves room for component-specific adjustments.
 */

:root {
  /* ========================================================================
     Z-INDEX SCALE - Layering System
     Organized from bottom to top of the stack
     ======================================================================== */

  /* Base layer - Normal document flow */
  --ds-z-index-base: 0;

  /* Dropdown layer - Select menus, autocomplete, etc */
  --ds-z-index-dropdown: 1000;

  /* Sticky elements - Sticky headers, footers */
  --ds-z-index-sticky: 1100;

  /* Fixed elements - Fixed navigation, banners */
  --ds-z-index-fixed: 1200;

  /* Overlay backdrop - Modal/drawer backdrops */
  --ds-z-index-overlay: 1300;

  /* Drawer - Side panels */
  --ds-z-index-drawer: 1400;

  /* Modal/Dialog - Modal windows */
  --ds-z-index-modal: 1500;

  /* Popover - Context menus, popovers */
  --ds-z-index-popover: 1600;

  /* Tooltip - Tooltips and hints */
  --ds-z-index-tooltip: 1700;

  /* Notification/Toast - Toast messages, notifications */
  --ds-z-index-notification: 1800;

  /* Maximum - Highest priority elements */
  --ds-z-index-max: 9999;

  /* ========================================================================
     COMPONENT-SPECIFIC Z-INDEX
     Specific layers for common component scenarios
     ======================================================================== */

  /* Navigation */
  --ds-z-index-navbar: var(--ds-z-index-fixed);
  --ds-z-index-sidebar: var(--ds-z-index-drawer);
  --ds-z-index-navbar-dropdown: calc(var(--ds-z-index-navbar) + 10);

  /* Menus */
  --ds-z-index-menu: var(--ds-z-index-dropdown);
  --ds-z-index-submenu: calc(var(--ds-z-index-menu) + 10);
  --ds-z-index-context-menu: var(--ds-z-index-popover);

  /* Overlays */
  --ds-z-index-modal-backdrop: var(--ds-z-index-overlay);
  --ds-z-index-modal-content: var(--ds-z-index-modal);
  --ds-z-index-drawer-backdrop: var(--ds-z-index-overlay);
  --ds-z-index-drawer-content: var(--ds-z-index-drawer);

  /* Feedback */
  --ds-z-index-toast: var(--ds-z-index-notification);
  --ds-z-index-alert: calc(var(--ds-z-index-base) + 1);
  --ds-z-index-banner: var(--ds-z-index-sticky);

  /* Forms */
  --ds-z-index-select-dropdown: var(--ds-z-index-dropdown);
  --ds-z-index-datepicker: var(--ds-z-index-dropdown);
  --ds-z-index-autocomplete: var(--ds-z-index-dropdown);

  /* Utility */
  --ds-z-index-loading-overlay: calc(var(--ds-z-index-modal) + 100);
  --ds-z-index-skip-link: var(--ds-z-index-max);

  /* ========================================================================
     RELATIVE Z-INDEX
     For elements that need layering within their stacking context
     ======================================================================== */
  --ds-z-index-relative-below: -1;
  --ds-z-index-relative-base: 0;
  --ds-z-index-relative-above: 1;
  --ds-z-index-relative-top: 10;
}


}
