     ───────────────────────────────────────────────────────────────────────────── */
  --ds-rate-color: #d4d4d4;
  --ds-rate-color-active: #fbbf24;
  --ds-rate-color-hover: #fcd34d;

  /* ─────────────────────────────────────────────────────────────────────────────
     STATISTIC
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-statistic-title-color: #737373;
  --ds-statistic-value-color: #171717;
  --ds-statistic-prefix-color: #525252;
  --ds-statistic-suffix-color: #525252;

