  --ds-list-bg: #ffffff;
  --ds-list-item-bg-hover: #fafafa;
  --ds-list-item-border: #e5e5e5;
  --ds-list-item-padding: 0.75rem 1rem;
  --ds-list-border-color: var(--ds-color-border);
  --ds-list-split-color: var(--ds-color-border-subtle);
  --ds-list-skeleton-bg: var(--ds-color-bg-tertiary);
  --ds-list-meta-description-color: var(--ds-color-text-secondary);

  /* ─────────────────────────────────────────────────────────────────────────────
     FLOAT BUTTON
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-floatbutton-shadow: var(--ds-shadow-dialog);
  --ds-floatbutton-hover-shadow: var(--ds-shadow-lg);
  --ds-floatbutton-default-bg: var(--ds-color-bg-elevated);
  --ds-floatbutton-default-color: var(--ds-color-text-secondary);
  --ds-floatbutton-primary-bg: var(--ds-color-primary);
  --ds-floatbutton-primary-color: var(--ds-color-text-on-primary);
  --ds-floatbutton-badge-bg: var(--ds-color-error);
  --ds-floatbutton-badge-color: var(--ds-color-text-on-primary);
  --ds-floatbutton-description-color: var(--ds-color-text-secondary);

  /* ─────────────────────────────────────────────────────────────────────────────
     COMMAND PALETTE
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-command-palette-backdrop: var(--ds-color-bg-overlay);
  --ds-command-palette-bg: var(--ds-color-bg-elevated);
  --ds-command-palette-shadow: var(--ds-shadow-dialog);
  --ds-command-palette-border: var(--ds-color-border);
  --ds-command-palette-item-hover-bg: var(--ds-color-bg-hover);
  --ds-command-palette-group-color: var(--ds-color-text-muted);
  --ds-command-palette-empty-color: var(--ds-color-text-muted);
  --ds-command-palette-shortcut-border: var(--ds-color-border);

  /* ─────────────────────────────────────────────────────────────────────────────
     LIVE FEED
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-live-feed-bg: var(--ds-color-bg-elevated);
  --ds-live-feed-border: var(--ds-color-border);
  --ds-live-feed-refresh-color: var(--ds-color-text-secondary);
  --ds-live-feed-new-bg: var(--ds-color-info-bg);
  --ds-live-feed-new-border: var(--ds-color-info-border);
  --ds-live-feed-new-color: var(--ds-color-info);
  --ds-live-feed-badge-bg: var(--ds-color-primary);
  --ds-live-feed-badge-color: var(--ds-color-text-on-primary);
  --ds-live-feed-empty-color: var(--ds-color-text-muted);
  --ds-live-feed-load-more-color: var(--ds-color-primary);
  --ds-live-feed-skeleton-bg: var(--ds-color-bg-tertiary);

  /* ─────────────────────────────────────────────────────────────────────────────
     STATS GRID
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-stats-grid-card-bg: var(--ds-color-bg-elevated);
  --ds-stats-grid-card-border: var(--ds-color-border);
  --ds-stats-grid-card-filled-bg: var(--ds-color-bg-secondary);
  --ds-stats-grid-card-glass-bg: var(--ds-color-alpha-white-50);
  --ds-stats-grid-card-glass-border: var(--ds-color-alpha-white-20);
  --ds-stats-grid-hover-shadow: var(--ds-shadow-md);
  --ds-stats-grid-label-color: var(--ds-color-text-secondary);
  --ds-stats-grid-value-color: var(--ds-color-text-primary);
  --ds-stats-grid-description-color: var(--ds-color-text-muted);
  --ds-stats-grid-trend-positive: var(--ds-color-success);
  --ds-stats-grid-trend-negative: var(--ds-color-error);
  --ds-stats-grid-trend-neutral: var(--ds-color-text-muted);
  --ds-stats-grid-skeleton-bg: var(--ds-color-bg-tertiary);
  --ds-stats-grid-skeleton-wave-gradient:
    linear-gradient(
      90deg,
      var(--ds-color-alpha-black-10) 25%,
      var(--ds-color-alpha-black-20) 37%,
      var(--ds-color-alpha-black-10) 63%
    );

  /* ─────────────────────────────────────────────────────────────────────────────
     DESCRIPTIONS
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-descriptions-label-color: #737373;
  --ds-descriptions-content-color: #171717;
  --ds-descriptions-border: #e5e5e5;
  --ds-descriptions-bg: #fafafa;

  /* ─────────────────────────────────────────────────────────────────────────────
     BACK TOP
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-backtop-bg: #171717;
  --ds-backtop-bg-hover: #000000;
  --ds-backtop-color: #ffffff;
  --ds-backtop-shadow: var(--ds-shadow-md);
  --ds-backtop-radius: var(--ds-radius-full);

  /* ─────────────────────────────────────────────────────────────────────────────
     AFFIX
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-affix-shadow: var(--ds-shadow-md);

  /* ─────────────────────────────────────────────────────────────────────────────
     ANCHOR
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-anchor-link-color: #737373;
  --ds-anchor-link-color-active: #171717;
  --ds-anchor-ink-color: #171717;
  --ds-anchor-border-color: #e5e5e5;

  /* ─────────────────────────────────────────────────────────────────────────────
     WATERMARK
     ───────────────────────────────────────────────────────────────────────────── */
  --ds-watermark-color: rgba(0, 0, 0, 0.05);
}

/* ───────────────────────────────────────────────────────────────────────────────
   DARK THEME
   ─────────────────────────────────────────────────────────────────────────────── */
:root[data-theme='dark'],
html[data-theme='dark'],
html.dark {
  color-scheme: dark;

  --ds-color-bg-primary: #0b1220;
  --ds-color-bg-secondary: #111827;
  --ds-color-bg-tertiary: #172033;
  --ds-color-bg-elevated: #182235;
  --ds-color-bg-overlay: rgba(2, 6, 23, 0.88);
  --ds-color-surface: #101826;
  --ds-color-surface-muted: #152033;

  --ds-color-text-primary: #f3f4f6;
  --ds-color-text-secondary: #cbd5e1;
  --ds-color-text-tertiary: #94a3b8;
  --ds-color-text-muted: #94a3b8;
  --ds-color-text-on-primary: #ffffff;
  --ds-color-text-inverse: #020617;

  --ds-color-border-primary: #334155;
  --ds-color-border-secondary: #1e293b;
  --ds-color-border-focus: var(--ds-color-primary-400);
  /* Dark-surface focus ring must read >=3:1 on the dark canvas; the primary-400
     tint clears it on #0b1220 (WO-ENG-04). */
  --ds-focus-ring-color: var(--ds-color-primary-400);

  --ds-color-neutral-0: #020617;
  --ds-color-neutral-50: #0b1220;
  --ds-color-neutral-100: #111827;
  --ds-color-neutral-200: #1f2937;
  --ds-color-neutral-300: #334155;
  --ds-color-neutral-400: #475569;
  --ds-color-neutral-500: #64748b;
  --ds-color-neutral-600: #94a3b8;
  --ds-color-neutral-700: #cbd5e1;
  --ds-color-neutral-800: #e2e8f0;
  --ds-color-neutral-900: #f8fafc;

  --ds-text-primary: var(--ds-color-text-primary);
  --ds-text-secondary: var(--ds-color-text-secondary);
  --ds-bg-primary: var(--ds-color-bg-primary);
  --ds-bg-secondary: var(--ds-color-bg-secondary);

  --ds-card-bg: var(--ds-color-bg-elevated);
  --ds-card-border-default: var(--ds-color-border-secondary);
  --ds-card-shadow-sm: 0 1px 2px rgba(2, 6, 23, 0.35);
  --ds-card-shadow-md: 0 10px 24px rgba(2, 6, 23, 0.35);

  --ds-input-bg: var(--ds-color-bg-tertiary);
  --ds-input-color: var(--ds-color-text-primary);
  --ds-input-border: var(--ds-color-border-primary);
  --ds-input-border-focus: var(--ds-color-primary-400);
  --ds-input-placeholder: var(--ds-color-text-tertiary);

  --ds-list-background-color: var(--ds-color-bg-elevated);
  --ds-list-item-background-color: var(--ds-color-bg-elevated);
  --ds-list-item-hover-background-color: color-mix(in srgb, var(--ds-color-primary-500) 10%, var(--ds-color-bg-elevated));
  --ds-list-border-color: var(--ds-color-border-secondary);
  --ds-list-text-color: var(--ds-color-text-primary);
  --ds-list-secondary-text-color: var(--ds-color-text-secondary);

  --ds-modal-title-color: var(--ds-color-text-primary);
  --ds-modal-body-color: var(--ds-color-text-secondary);
  --ds-modal-header-border: var(--ds-color-border-secondary);
  --ds-modal-footer-border: var(--ds-color-border-secondary);
  --ds-modal-close-color: var(--ds-color-text-secondary);

  --ds-menu-dark-bg: var(--ds-color-bg-secondary);
  --ds-menu-dark-item-color: var(--ds-color-text-secondary);
  --ds-menu-item-color: var(--ds-color-text-secondary);
  --ds-menu-item-color-hover: var(--ds-color-text-primary);
  --ds-menu-item-bg-hover: color-mix(in srgb, var(--ds-color-primary-500) 14%, transparent);
  --ds-menu-item-bg-active: color-mix(in srgb, var(--ds-color-primary-500) 18%, transparent);

  --ds-descriptions-label-color: var(--ds-color-text-tertiary);
  --ds-descriptions-content-color: var(--ds-color-text-primary);
  --ds-descriptions-border: var(--ds-color-border-secondary);
  --ds-descriptions-bg: var(--ds-color-bg-secondary);

  --ds-anchor-link-color: var(--ds-color-text-secondary);
  --ds-anchor-link-color-active: var(--ds-color-text-primary);
  --ds-anchor-ink-color: var(--ds-color-primary-400);
  --ds-anchor-border-color: var(--ds-color-border-secondary);

  --ds-watermark-color: rgba(255, 255, 255, 0.06);
}

}

/* Layer 2: Component tokens */
@layer rottay-components {
/**
 * Avatar Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Avatar component.
 * Includes sizes, shapes, variants, status indicators, and group settings.
 */

:root {
  /* ========================================================================
     SIZES - Avatar Dimensions
     Seven size variants from xs to 3xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small (24px) */
  --ds-avatar-xs-size: 1.5rem;           /* 24px */
  --ds-avatar-xs-font-size: 0.625rem;    /* 10px */
  --ds-avatar-xs-status-size: 0.375rem;  /* 6px */
  --ds-avatar-xs-border-width: 1px;

  /* SM - Small (32px) */
  --ds-avatar-sm-size: 2rem;             /* 32px */
  --ds-avatar-sm-font-size: 0.75rem;     /* 12px */
  --ds-avatar-sm-status-size: 0.5rem;    /* 8px */
  --ds-avatar-sm-border-width: 1.5px;

  /* MD - Medium (40px - Default) */
  --ds-avatar-md-size: 2.5rem;           /* 40px */
  --ds-avatar-md-font-size: 0.875rem;    /* 14px */
  --ds-avatar-md-status-size: 0.625rem;  /* 10px */
  --ds-avatar-md-border-width: 2px;

  /* LG - Large (48px) */
  --ds-avatar-lg-size: 3rem;             /* 48px */
  --ds-avatar-lg-font-size: 1rem;        /* 16px */
  --ds-avatar-lg-status-size: 0.75rem;   /* 12px */
  --ds-avatar-lg-border-width: 2px;

  /* XL - Extra Large (56px) */
  --ds-avatar-xl-size: 3.5rem;           /* 56px */
  --ds-avatar-xl-font-size: 1.125rem;    /* 18px */
  --ds-avatar-xl-status-size: 0.875rem;  /* 14px */
  --ds-avatar-xl-border-width: 2.5px;

  /* 2XL - 2x Extra Large (64px) */
  --ds-avatar-2xl-size: 4rem;            /* 64px */
  --ds-avatar-2xl-font-size: 1.25rem;    /* 20px */
  --ds-avatar-2xl-status-size: 1rem;     /* 16px */
  --ds-avatar-2xl-border-width: 3px;

  /* 3XL - 3x Extra Large (96px) */
  --ds-avatar-3xl-size: 6rem;            /* 96px */
  --ds-avatar-3xl-font-size: 1.75rem;    /* 28px */
  --ds-avatar-3xl-status-size: 1.25rem;  /* 20px */
  --ds-avatar-3xl-border-width: 4px;

  /* Default size (can be overridden) */
  --ds-avatar-default-size: var(--ds-avatar-md-size);
  --ds-avatar-default-font-size: var(--ds-avatar-md-font-size);
  --ds-avatar-default-status-size: var(--ds-avatar-md-status-size);
  --ds-avatar-default-border-width: var(--ds-avatar-md-border-width);

  /* ========================================================================
     SHAPES - Avatar Border Radius
     Three shape variants: circle, square, rounded
     ======================================================================== */
  --ds-avatar-circle-radius: 50%;                          /* Fully rounded */
  --ds-avatar-square-radius: 0;                            /* No rounding */
  --ds-avatar-rounded-radius: var(--ds-radius-md, 0.5rem);    /* 8px rounded corners */

  /* Default shape */
  --ds-avatar-default-shape: var(--ds-avatar-circle-radius);

  /* ========================================================================
     VARIANTS - Avatar Color Variants
     Different visual styles for avatars
     ======================================================================== */

  /* Default variant (neutral) */
  --ds-avatar-default-bg: var(--ds-color-neutral-100);
  --ds-avatar-default-color: var(--ds-color-neutral-600);
  --ds-avatar-default-border-color: var(--ds-color-neutral-200);
  --ds-avatar-default-shadow: none;

  /* Primary variant */
  --ds-avatar-primary-bg: var(--ds-color-primary-100);
  --ds-avatar-primary-color: var(--ds-color-primary-700);
  --ds-avatar-primary-border-color: var(--ds-color-primary-200);
  --ds-avatar-primary-shadow: 0 2px 8px rgba(0, 102, 204, 0.15);

  /* Secondary variant */
  --ds-avatar-secondary-bg: var(--ds-color-secondary-100);
  --ds-avatar-secondary-color: var(--ds-color-secondary-700);
  --ds-avatar-secondary-border-color: var(--ds-color-secondary-200);
  --ds-avatar-secondary-shadow: 0 2px 8px rgba(107, 107, 212, 0.15);

  /* Success variant */
  --ds-avatar-success-bg: var(--ds-color-success-100);
  --ds-avatar-success-color: var(--ds-color-success-700);
  --ds-avatar-success-border-color: var(--ds-color-success-200);
  --ds-avatar-success-shadow: 0 2px 8px rgba(34, 197, 94, 0.15);

  /* Warning variant */
  --ds-avatar-warning-bg: var(--ds-color-warning-100);
  --ds-avatar-warning-color: var(--ds-color-warning-700);
  --ds-avatar-warning-border-color: var(--ds-color-warning-200);
  --ds-avatar-warning-shadow: 0 2px 8px rgba(245, 158, 11, 0.15);

  /* Error variant */
  --ds-avatar-error-bg: var(--ds-color-error-100);
  --ds-avatar-error-color: var(--ds-color-error-700);
  --ds-avatar-error-border-color: var(--ds-color-error-200);
  --ds-avatar-error-shadow: 0 2px 8px rgba(239, 68, 68, 0.15);

  /* Gradient variant */
  --ds-avatar-gradient-bg: linear-gradient(135deg, var(--ds-color-primary-400) 0%, var(--ds-color-secondary-500) 100%);
  --ds-avatar-gradient-color: var(--ds-color-white);
  --ds-avatar-gradient-border-color: transparent;
  --ds-avatar-gradient-shadow: 0 4px 12px rgba(0, 102, 204, 0.2);

  /* ========================================================================
     STATUS INDICATORS
     Color indicators for online/offline/away/busy states
     ======================================================================== */
  --ds-avatar-status-online-color: var(--ds-color-success-500);
  --ds-avatar-status-offline-color: var(--ds-color-neutral-400);
  --ds-avatar-status-away-color: var(--ds-color-warning-500);
  --ds-avatar-status-busy-color: var(--ds-color-error-500);

  /* Status indicator position and sizing */
  --ds-avatar-status-offset: 0;          /* Distance from edge */
  --ds-avatar-status-border-width: 2px;  /* White border around status */
  --ds-avatar-status-border-color: var(--ds-color-white);

  /* ========================================================================
     AVATAR GROUP
     Settings for overlapping avatar groups
     ======================================================================== */
  --ds-avatar-group-compact-spacing: -0.5rem;   /* -8px overlap */
  --ds-avatar-group-normal-spacing: -0.25rem;   /* -4px overlap */
  --ds-avatar-group-loose-spacing: 0.25rem;     /* 4px gap */

  /* Default group spacing */
  --ds-avatar-group-default-spacing: var(--ds-avatar-group-normal-spacing);

  /* Group max count settings */
  --ds-avatar-group-max-count: 5;                /* Max avatars before showing +N */
  --ds-avatar-group-overflow-bg: var(--ds-color-neutral-200);
  --ds-avatar-group-overflow-color: var(--ds-color-neutral-700);
  --ds-avatar-group-overflow-font-weight: var(--ds-font-weight-medium);

  /* ========================================================================
     INTERACTIONS
     Hover, focus, and active states
     ======================================================================== */
  --ds-avatar-hover-scale: 1.05;
  --ds-avatar-hover-shadow: 0 4px 12px rgba(0, 0, 0, 0.1);
  --ds-avatar-hover-border-color: var(--ds-color-primary-300);

  --ds-avatar-focus-ring-width: 2px;
  --ds-avatar-focus-ring-color: var(--ds-color-primary-500);
  --ds-avatar-focus-ring-offset: 2px;

  --ds-avatar-active-scale: 0.98;

  /* ========================================================================
     BADGE/NOTIFICATION
     For notification badges on avatars
     ======================================================================== */
  --ds-avatar-badge-size: 1rem;                  /* 16px */
  --ds-avatar-badge-font-size: 0.625rem;         /* 10px */
  --ds-avatar-badge-bg: var(--ds-color-error-500);
  --ds-avatar-badge-color: var(--ds-color-white);
  --ds-avatar-badge-border-width: 2px;
  --ds-avatar-badge-border-color: var(--ds-color-white);
  --ds-avatar-badge-offset-top: 0;
  --ds-avatar-badge-offset-right: 0;

  /* ========================================================================
     LOADING STATE
     Skeleton/loading appearance
     ======================================================================== */
  --ds-avatar-loading-bg: var(--ds-color-neutral-100);
  --ds-avatar-loading-animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;

  /* ========================================================================
     TOUCH TARGETS
     Minimum touch target size for accessibility
     ======================================================================== */
  --ds-avatar-touch-target-min: 2.75rem;  /* 44px - WCAG AAA minimum */

  /* ========================================================================
     TRANSITIONS
     Animation timing for state changes
     ======================================================================== */
  --ds-avatar-transition-duration: 0.2s;
  --ds-avatar-transition-timing: ease-in-out;
  --ds-avatar-transition: all var(--ds-avatar-transition-duration) var(--ds-avatar-transition-timing);

  /* ========================================================================
     IMAGE SETTINGS
     Settings for image rendering within avatars
     ======================================================================== */
  --ds-avatar-image-object-fit: cover;
  --ds-avatar-image-object-position: center;

  /* ========================================================================
     FALLBACK ICON
     Settings for icon fallback when no image is provided
     ======================================================================== */
  --ds-avatar-fallback-icon-size: 60%;  /* Icon size relative to avatar */
  --ds-avatar-fallback-icon-color: currentColor;
}

}
@layer rottay-components {
/**
 * Badge Component Tokens - Rottay Design System
 *
 * Design tokens specific to the Badge component.
 * Includes sizes, dot sizes, variants, and styling properties.
 */

:root {
  /* ========================================================================
     SIZES - Badge Dimensions
     Five size variants from xs to xl with corresponding properties
     ======================================================================== */

  /* XS - Extra Small */
  --ds-badge-xs-min-width: 0.875rem;       /* 14px */
  --ds-badge-xs-height: 0.875rem;          /* 14px */
  --ds-badge-xs-font-size: 0.5625rem;      /* 9px */

  /* SM - Small */
  --ds-badge-sm-min-width: 1rem;           /* 16px */
  --ds-badge-sm-height: 1rem;              /* 16px */
  --ds-badge-sm-font-size: 0.625rem;       /* 10px */

  /* MD - Medium (Default) */
  --ds-badge-md-min-width: 1.25rem;        /* 20px */
  --ds-badge-md-height: 1.25rem;           /* 20px */
  --ds-badge-md-font-size: 0.75rem;        /* 12px */

  /* LG - Large */
  --ds-badge-lg-min-width: 1.5rem;         /* 24px */
  --ds-badge-lg-height: 1.5rem;            /* 24px */
  --ds-badge-lg-font-size: 0.875rem;       /* 14px */

  /* XL - Extra Large */
  --ds-badge-xl-min-width: 1.75rem;        /* 28px */
  --ds-badge-xl-height: 1.75rem;           /* 28px */
  --ds-badge-xl-font-size: 1rem;           /* 16px */

  /* Default size (can be overridden) */
  --ds-badge-default-min-width: var(--ds-badge-md-min-width);
  --ds-badge-default-height: var(--ds-badge-md-height);
  --ds-badge-default-font-size: var(--ds-badge-md-font-size);

  /* ========================================================================
     DOT SIZES - Badge Dot Indicator Dimensions
     Diameter of dot badges for each size variant
     ======================================================================== */

  --ds-badge-dot-xs-size: 0.25rem;         /* 4px */
  --ds-badge-dot-sm-size: 0.375rem;        /* 6px */
  --ds-badge-dot-md-size: 0.5rem;          /* 8px */
  --ds-badge-dot-lg-size: 0.625rem;        /* 10px */
  --ds-badge-dot-xl-size: 0.75rem;         /* 12px */

  /* Default dot size */
  --ds-badge-dot-default-size: var(--ds-badge-dot-md-size);

  /* ========================================================================
     VARIANTS - Badge Color Variants
     Different visual styles for badges
     ======================================================================== */

  /* Default variant (neutral) */
  --ds-badge-default-bg: #d9d9d9;
  --ds-badge-default-color: var(--ds-color-white, #ffffff);
  --ds-badge-default-border: var(--ds-badge-border-color);

  /* Primary variant */
  --ds-badge-primary-bg: #1890ff;
  --ds-badge-primary-color: var(--ds-color-white, #ffffff);
  --ds-badge-primary-border: var(--ds-badge-primary-bg);

  /* Secondary variant */
  --ds-badge-secondary-bg: #722ed1;
  --ds-badge-secondary-color: var(--ds-color-white, #ffffff);
  --ds-badge-secondary-border: var(--ds-badge-secondary-bg);

  /* Success variant */
  --ds-badge-success-bg: #52c41a;
  --ds-badge-success-color: var(--ds-color-white, #ffffff);
  --ds-badge-success-border: var(--ds-badge-success-bg);

  /* Warning variant */
  --ds-badge-warning-bg: #faad14;
  --ds-badge-warning-color: var(--ds-color-white, #ffffff);
  --ds-badge-warning-border: var(--ds-badge-warning-bg);

  /* Error variant */
  --ds-badge-error-bg: #ff4d4f;
  --ds-badge-error-color: var(--ds-color-white, #ffffff);
  --ds-badge-error-border: var(--ds-badge-error-bg);

  /* Info variant */
  --ds-badge-info-bg: #1890ff;
  --ds-badge-info-color: var(--ds-color-white, #ffffff);
  --ds-badge-info-border: var(--ds-badge-info-bg);

  /* ========================================================================
     STATUS INDICATORS
     Color indicators for processing/default/success/error/warning states
     ======================================================================== */

  --ds-badge-status-processing-color: #1890ff;
  --ds-badge-status-default-color: #d9d9d9;
  --ds-badge-status-success-color: #52c41a;
