  );
  --ds-card-cover-content-color: var(--ds-color-white);

  /* ========================================================================
     VARIANTS
     Different card visual styles
     ======================================================================== */

  /* Default variant */
  --ds-card-default-bg: var(--ds-card-bg);
  --ds-card-default-border-color: var(--ds-card-border-color);
  --ds-card-default-shadow: var(--ds-card-shadow-default);

  /* Bordered variant (emphasized border, no shadow) */
  --ds-card-bordered-bg: var(--ds-card-bg);
  --ds-card-bordered-border-width: 2px;
  --ds-card-bordered-border-color: var(--ds-color-neutral-300);
  --ds-card-bordered-shadow: none;

  /* Flat variant (no border, no shadow) */
  --ds-card-flat-bg: var(--ds-card-bg);
  --ds-card-flat-border-width: 0;
  --ds-card-flat-shadow: none;

  /* Elevated variant (strong shadow, no border) */
  --ds-card-elevated-bg: var(--ds-card-bg);
  --ds-card-elevated-border-width: 0;
  --ds-card-elevated-shadow: var(--ds-card-shadow-lg);
  --ds-card-elevated-shadow-hover: var(--ds-card-shadow-xl);

  /* Ghost variant (transparent background) */
  --ds-card-ghost-bg: transparent;
  --ds-card-ghost-border-color: var(--ds-color-neutral-200);
  --ds-card-ghost-shadow: none;

  /* ========================================================================
     INTERACTIVE STATES
     Clickable/hoverable cards
     ======================================================================== */
  --ds-card-interactive-cursor: pointer;
  --ds-card-interactive-transform-hover: translateY(-2px);
