  --ds-modal-slide-top-to: 0;
  --ds-modal-slide-duration: 0.3s;
  --ds-modal-slide-timing: cubic-bezier(0.16, 1, 0.3, 1);

  /* Slide from bottom (mobile) */
  --ds-modal-slide-bottom-from: 100%;
  --ds-modal-slide-bottom-to: 0;

  /* Combined transition */
  --ds-modal-transition: all var(--ds-modal-fade-duration) var(--ds-modal-fade-timing);

  /* ========================================================================
     VARIANTS - Modal Types
     Different modal styles for various use cases
     ======================================================================== */

  /* Centered modal (default) */
  --ds-modal-centered-align: center;
  --ds-modal-centered-justify: center;

  /* Top modal */
  --ds-modal-top-align: flex-start;
  --ds-modal-top-justify: center;
  --ds-modal-top-margin-top: 4rem;

  /* Drawer/Side modal */
  --ds-modal-drawer-width: 24rem;          /* 384px */
  --ds-modal-drawer-max-width: 90vw;
  --ds-modal-drawer-height: 100vh;
  --ds-modal-drawer-border-radius: 0;

  /* Bottom sheet (mobile) */
  --ds-modal-bottom-sheet-width: 100%;
  --ds-modal-bottom-sheet-max-height: 90vh;
  --ds-modal-bottom-sheet-border-radius-top: var(--ds-radius-2xl);
  --ds-modal-bottom-sheet-border-radius-bottom: 0;

  /* ========================================================================
     SEMANTIC VARIANTS
     Colored modals for different contexts
     ======================================================================== */

  /* Confirmation modal */
  --ds-modal-confirm-icon-color: var(--ds-color-primary-500);
  --ds-modal-confirm-icon-bg: var(--ds-color-primary-100);

  /* Success modal */
  --ds-modal-success-icon-color: var(--ds-color-success-500);
  --ds-modal-success-icon-bg: var(--ds-color-success-100);

  /* Warning modal */
  --ds-modal-warning-icon-color: var(--ds-color-warning-500);
  --ds-modal-warning-icon-bg: var(--ds-color-warning-100);

  /* Error/Destructive modal */
  --ds-modal-error-icon-color: var(--ds-color-error-500);
  --ds-modal-error-icon-bg: var(--ds-color-error-100);

  /* Info modal */
  --ds-modal-info-icon-color: var(--ds-color-info-500);
  --ds-modal-info-icon-bg: var(--ds-color-info-100);

  /* ========================================================================
     ICON
     Icon in header or content
     ======================================================================== */
  --ds-modal-icon-size: 3rem;              /* 48px */
  --ds-modal-icon-size-sm: 2rem;           /* 32px */
  --ds-modal-icon-size-lg: 4rem;           /* 64px */
  --ds-modal-icon-margin-bottom: 1rem;

  /* ========================================================================
     SCROLLABLE CONTENT
     Settings for scrolling modal body
     ======================================================================== */
  --ds-modal-scroll-padding: 0.5rem;
  --ds-modal-scroll-shadow-top: inset 0 8px 8px -8px rgba(0, 0, 0, 0.1);
  --ds-modal-scroll-shadow-bottom: inset 0 -8px 8px -8px rgba(0, 0, 0, 0.1);

  /* ========================================================================
     LOADING STATE
     Modal loading indicator
     ======================================================================== */
  --ds-modal-loading-overlay-bg: var(--ds-color-alpha-white-80);
  --ds-modal-loading-spinner-color: var(--ds-color-primary-500);
  --ds-modal-loading-spinner-size: 2rem;

  /* ========================================================================
     NESTED MODALS
     Stacking multiple modals
     ======================================================================== */
  --ds-modal-nested-z-index-offset: 10;
  --ds-modal-nested-overlay-bg: var(--ds-color-alpha-black-30);

  /* ========================================================================
     ACCESSIBILITY
     Focus trap and keyboard navigation
     ======================================================================== */
  --ds-modal-focus-ring: var(--ds-shadow-focus-ring);
  --ds-modal-focus-ring-offset: 2px;
  --ds-modal-focus-outline: none;

  /* ========================================================================
     RESPONSIVE
     Mobile-specific adjustments
     ======================================================================== */
  --ds-modal-mobile-width: calc(100vw - 2rem);
  --ds-modal-mobile-max-height: calc(100vh - 2rem);
  --ds-modal-mobile-padding: 1rem;
  --ds-modal-mobile-border-radius: var(--ds-radius-lg);

  /* ========================================================================
     DIVIDER
     Internal modal dividers
     ======================================================================== */
  --ds-modal-divider-width: 1px;
  --ds-modal-divider-color: var(--ds-color-neutral-200);
  --ds-modal-divider-margin-y: 1rem;

  /* ========================================================================
     BACKDROP BLUR
     Glassmorphism effect
     ======================================================================== */
  --ds-modal-glass-bg: rgba(255, 255, 255, 0.9);
  --ds-modal-glass-backdrop-filter: blur(12px) saturate(180%);
  --ds-modal-glass-border: 1px solid rgba(255, 255, 255, 0.3);
}

