  --ds-select-filled-border-color: transparent;

  /* Flushed variant */
  --ds-select-flushed-border-radius: 0;
  --ds-select-flushed-border-width: 0 0 1px 0;

  /* ========================================================================
     STATUS VARIANTS - Semantic States
     Success, warning, error status
     ======================================================================== */

  /* Success status */
  --ds-select-success-border-color: var(--ds-color-success-500);
  --ds-select-success-border-color-focus: var(--ds-color-success-600);
  --ds-select-success-shadow-focus: var(--ds-shadow-focus-ring-success);

  /* Warning status */
