  --ds-select-warning-shadow-focus: var(--ds-shadow-focus-ring-warning);

  /* Error status */
  --ds-select-error-border-color: var(--ds-color-error-500);
  --ds-select-error-border-color-focus: var(--ds-color-error-600);
  --ds-select-error-shadow-focus: var(--ds-shadow-focus-ring-error);

  /* ========================================================================
     DROPDOWN - Dropdown Panel Styling
     Settings for the dropdown panel
     ======================================================================== */
  --ds-select-dropdown-bg: var(--ds-color-white);
  --ds-select-dropdown-border-color: var(--ds-color-neutral-200);
  --ds-select-dropdown-border-radius: var(--ds-radius-md);
  --ds-select-dropdown-shadow: var(--ds-shadow-lg);
  --ds-select-dropdown-max-height: 16rem;   /* 256px */
  --ds-select-dropdown-padding: 0.25rem;    /* 4px */
  --ds-select-dropdown-z-index: 1050;

