  --ds-list-split-color: var(--ds-color-neutral-200, #e5e7eb);
  --ds-list-split-width: 1px;

  /* ========================================================================
     COLORS - List background and text colors
     ======================================================================== */

  --ds-list-background-color: var(--ds-color-white, #ffffff);
  --ds-list-item-background-color: transparent;
  --ds-list-item-hover-background-color: var(--ds-color-neutral-50, #f9fafb);

  --ds-list-text-color: var(--ds-color-neutral-900, #111827);
  --ds-list-secondary-text-color: var(--ds-color-neutral-500, #6b7280);

  /* ========================================================================
     HEADER & FOOTER
     ======================================================================== */

  --ds-list-header-padding-vertical: 12px;
  --ds-list-header-padding-horizontal: 16px;
  --ds-list-header-font-size: 14px;
  --ds-list-header-font-weight: 600;
  --ds-list-header-background-color: var(--ds-color-neutral-50, #f9fafb);

  --ds-list-footer-padding-vertical: 12px;
  --ds-list-footer-padding-horizontal: 16px;
  --ds-list-footer-font-size: 14px;
  --ds-list-footer-background-color: var(--ds-color-neutral-50, #f9fafb);

  /* ========================================================================
     LIST ITEM META - Avatar, title, description
     ======================================================================== */

  --ds-list-meta-avatar-margin-right: 16px;
  --ds-list-meta-title-font-size: 14px;
  --ds-list-meta-title-font-weight: 500;
  --ds-list-meta-title-color: var(--ds-color-neutral-900, #111827);
  --ds-list-meta-description-font-size: 12px;
  --ds-list-meta-description-color: var(--ds-color-neutral-500, #6b7280);
  --ds-list-meta-description-margin-top: 4px;

  /* ========================================================================
     LIST ITEM ACTIONS
     ======================================================================== */

  --ds-list-actions-gap: 16px;
  --ds-list-actions-color: var(--ds-color-primary, #1890ff);
  --ds-list-actions-hover-color: var(--ds-color-primary-600, #0066cc);

  /* ========================================================================
     LIST ITEM EXTRA
     ======================================================================== */

  --ds-list-extra-margin-left: 24px;

  /* ========================================================================
     EMPTY STATE
     ======================================================================== */

  --ds-list-empty-padding: 32px;
  --ds-list-empty-text-color: var(--ds-color-neutral-400, #9ca3af);
  --ds-list-empty-font-size: 14px;

  /* ========================================================================
     LOADING STATE
     ======================================================================== */

  --ds-list-loading-opacity: 0.6;
  --ds-list-loading-spinner-size: 24px;
  --ds-list-loading-spinner-color: var(--ds-color-primary, #1890ff);

  /* ========================================================================
     GRID LAYOUT
     ======================================================================== */

  --ds-list-grid-gutter: 16px;

  /* ========================================================================
     TRANSITIONS
     ======================================================================== */

  --ds-list-transition-duration: 0.2s;
  --ds-list-transition-timing: ease-in-out;
}

