@keyframes ds-surface-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ds-meter-sweep {
  from {
    transform: translateX(-100%);
  }

  to {
    transform: translateX(100%);
  }
}

@keyframes ds-command-home-spin {
  to {
    transform: rotate(360deg);
  }
}

:where(.ds-workspace-frame) {
  position: relative;
  isolation: isolate;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  border: 1px solid var(--ds-workspace-shell-border, var(--ds-color-border));
  border-radius: var(--ds-radius-md);
  color: var(--ds-color-text-primary);
  font-family: var(--ds-font-family-base);
  background: var(--ds-workspace-shell-bg);
  box-shadow: var(--ds-workspace-shell-shadow, var(--ds-card-shadow));
  animation: ds-surface-enter 180ms ease-out;
}

:where(.ds-workspace-frame--list) {
  --ds-workspace-shell-bg: linear-gradient(
    180deg,
    var(--ds-surface-card-bg) 0%,
    var(--ds-surface-canvas, var(--ds-surface-panel-bg)) 50%,
    color-mix(in srgb, var(--ds-color-primary) 4%, var(--ds-surface-panel-bg)) 100%
  );
}

:where(.ds-workspace-frame--detail) {
  --ds-workspace-shell-overlay: linear-gradient(
    180deg,
    color-mix(in srgb, var(--ds-color-primary) 5.5%, transparent) 0%,
    transparent 44%,
    color-mix(in srgb, var(--ds-color-secondary, var(--ds-color-primary)) 7%, transparent) 100%
  );
}

:where(.ds-workspace-frame--form) {
  overflow: visible;
  --ds-workspace-shell-bg: linear-gradient(
    180deg,
    var(--ds-surface-card-bg) 0%,
    var(--ds-surface-canvas, var(--ds-surface-panel-bg)) 46%,
    color-mix(in srgb, var(--ds-color-primary) 5%, var(--ds-surface-panel-bg)) 100%
  );
}

:where(.ds-workspace-frame)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: var(--ds-workspace-shell-overlay);
}

:where(.ds-workspace-frame__inner) {
  position: relative;
  z-index: 1;
}

:where(.ds-workspace-frame) > :not(:where(.ds-workspace-frame__inner)) {
  position: relative;
  z-index: 1;
}

:where(.ds-workspace-frame--padded) > :where(.ds-workspace-frame__inner) {
  padding: var(--ds-workspace-frame-padding, clamp(16px, 2.2vw, 28px));
}

:where(.ds-workspace-frame--loading) {
  min-height: min(720px, calc(100vh - 64px));
}

:where(.ds-workspace-grid) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, var(--ds-workflow-rail-width, 360px));
  gap: clamp(20px, 2.2vw, 32px);
  width: 100%;
}

:where(.ds-workspace-grid__main, .ds-workspace-grid__rail) {
  min-width: 0;
}

:where(.ds-command-grid) {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: var(--ds-command-grid-bg-strong);
  background-size: var(--ds-command-grid-size) var(--ds-command-grid-size);
  opacity: var(--ds-command-grid-opacity, 0.18);
}

:where(
  .ds-surface-hero,
  .ds-surface-card,
  .ds-surface-panel,
  .ds-surface-rail-card,
  .ds-surface-table-card,
  .ds-rich-card,
  .ds-metric-card,
  .ds-stat-card
) {
  color: var(--ds-color-text-primary);
}

:where(.ds-surface-hero) {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--ds-color-border-secondary);
  border-radius: var(--ds-radius-md);
  background: var(--ds-workspace-hero-bg);
  box-shadow: var(--ds-card-shadow);
}

:where(.ds-surface-card, .ds-surface-rail-card) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--ds-premium-card-border);
  border-radius: var(--ds-radius-md);
  background: var(--ds-premium-card-bg);
  background-clip: padding-box;
  box-shadow: var(--ds-card-shadow);
  animation: ds-surface-enter var(--ds-duration-slow, 300ms) var(--ds-ease-out, cubic-bezier(0.16, 1, 0.3, 1)) both;
  transition:
    border-color var(--ds-duration-fast, 150ms) ease,
    box-shadow var(--ds-duration-fast, 150ms) ease,
    transform var(--ds-duration-fast, 150ms) ease,
    filter var(--ds-duration-fast, 150ms) ease;
}

:where(.ds-surface-card, .ds-surface-rail-card)::before,
:where(.ds-surface-table-card)::before,
:where(.ds-rich-card)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    var(--ds-surface-card-grid-bg),
    var(--ds-premium-card-sheen);
  background-size:
    var(--ds-surface-card-grid-size) var(--ds-surface-card-grid-size),
    auto;
  opacity: 0.28;
  mask-image: linear-gradient(180deg, var(--ds-color-text-primary), transparent 82%);
  transition: opacity var(--ds-duration-fast, 150ms) ease;
}

:where(.ds-surface-card, .ds-surface-rail-card)::after,
:where(.ds-surface-table-card)::after,
:where(.ds-rich-card)::after {
  content: none;
}

:where(.ds-surface-card, .ds-surface-rail-card, .ds-surface-table-card, .ds-rich-card) > * {
  position: relative;
  z-index: 2;
}

:where(.ds-surface-card, .ds-surface-rail-card):hover {
  border-color: var(--ds-premium-card-border-hover);
  box-shadow: var(--ds-card-shadow-hover);
  transform: translateY(-1px);
  filter: saturate(1.01);
}

:where(.ds-surface-card, .ds-surface-rail-card):hover::before {
  opacity: 0.42;
}

:where(.ds-surface-panel) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--ds-color-border);
  border-radius: var(--ds-radius-sm);
  background: color-mix(in srgb, var(--ds-surface-panel-bg) 92%, var(--ds-surface-card-bg));
  transition:
    border-color var(--ds-duration-fast, 150ms) ease,
    background var(--ds-duration-fast, 150ms) ease,
    box-shadow var(--ds-duration-fast, 150ms) ease;
}

:where(.ds-surface-panel)::before {
