  :is(.ds-command-home-command-grid, .ds-workspace-grid) {
    grid-template-columns: 1fr;
  }

  :is(.ds-command-home-composer, .ds-ai-composer, .ds-command-home-search-card) {
    height: auto;
    min-height: var(--ds-command-home-compact-action-height);
  }
}

