  :is(.ds-command-home-hero) {
    align-items: flex-start;
    flex-direction: column;
  }

  :is(.ds-command-home-hero__status) {
    justify-content: flex-start;
  }

  :is(.ds-command-home-console) {
    min-height: auto;
    padding: 14px;
  }

  :is(.ds-command-home-message, .ds-ai-chat-message) {
    max-width: 100%;
  }

  :is(.ds-command-home-launchpad__grid, .ds-launchpad__grid) {
    grid-template-columns: 1fr;
  }

  :is(.ds-command-home-launchpad-card, .ds-launchpad-card) {
    grid-template-columns: auto minmax(0, 1fr);
  }

  :is(.ds-command-home-launchpad-card__arrow, .ds-launchpad-card__arrow) {
    display: none;
  }

  :is(.ds-command-home-composer__footer, .ds-ai-composer__footer) {
    align-items: stretch !important;
    flex-direction: column;
  }

  :is(.ds-command-home-send, .ds-ai-send) {
    width: 100%;
  }
}

/*
 * Command home runtime contract.
 *
 * These scoped selectors intentionally carry normal specificity so this DS-owned
 * surface wins over the generic Box/Flex/Stack/Button primitives that apps use
 * to compose it. The earlier pattern rules stay tokenized and reusable; this
 * layer preserves the actual rendered contract after moving the Home styles
 * out of app-local CSS.
 */
.ds-command-home-shell .ds-command-home-console {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 22px;
  justify-self: center;
  width: min(100%, var(--ds-command-home-max-width));
  max-width: var(--ds-command-home-max-width);
  min-width: 0;
  min-height: var(--ds-command-home-console-min-height);
  margin-inline: auto;
  padding: var(--ds-command-home-console-padding);
  overflow: hidden;
  border: 1px solid var(--ds-command-home-panel-border);
  border-radius: 12px;
  background: var(--ds-command-home-console-bg);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    var(--ds-command-home-panel-shadow);
}

.ds-command-home-shell .ds-command-home-hero,
.ds-command-home-shell .ds-launchpad,
.ds-command-home-shell .ds-command-home-rail-card,
.ds-command-home-shell .ds-command-home-brief,
.ds-command-home-shell .ds-ai-composer {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--ds-command-home-panel-border);
  border-radius: 10px;
  background-clip: padding-box;
  background: var(--ds-command-home-surface-bg);
  box-shadow:
    0 1px 2px rgba(22, 42, 67, 0.08),
    0 12px 28px rgba(22, 42, 67, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.ds-command-home-shell .ds-command-home-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  width: 100%;
  padding: 16px 18px;
  background: var(--ds-command-home-hero-bg);
}

.ds-command-home-shell .ds-command-home-hero__status {
  justify-content: flex-end;
  justify-self: end;
  max-width: min(100%, 430px);
  min-width: 0;
}

.ds-command-home-shell .ds-command-home-hero__mark,
.ds-command-home-shell .ds-command-home-capability__icon,
.ds-command-home-shell .ds-command-home-prompt-row__icon,
.ds-command-home-shell .ds-command-home-brief__icon,
.ds-command-home-shell .ds-ai-chat-message-avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--ds-command-home-icon-border);
  border-radius: var(--ds-radius-sm, 6px);
  color: var(--ds-color-primary);
  background: var(--ds-command-home-icon-bg);
}

.ds-command-home-shell .ds-command-home-hero__mark {
  width: 42px;
  height: 42px;
}

.ds-command-home-shell .ds-command-home-eyebrow,
.ds-command-home-shell .ds-command-home-section-title,
.ds-command-home-shell .ds-launchpad-card__eyebrow,
.ds-command-home-shell .ds-command-home-next-move__action {
  color: var(--ds-color-primary) !important;
  font-family: var(--ds-font-family-mono) !important;
  font-size: 0.6875rem !important;
  font-weight: 820 !important;
  letter-spacing: 0 !important;
  line-height: 1.2 !important;
  text-transform: uppercase !important;
}

.ds-command-home-shell .ds-command-home-title {
  color: var(--ds-color-text-primary) !important;
  font-size: var(--ds-command-home-title-size, 2rem) !important;
  font-weight: 880 !important;
  letter-spacing: 0 !important;
