}

.ds-tag--primary {
  background-color: var(--ds-tag-primary-bg);
  color: var(--ds-tag-primary-color);
  border-color: var(--ds-tag-primary-border);
}

.ds-tag--success {
  background-color: var(--ds-tag-success-bg);
  color: var(--ds-tag-success-color);
  border-color: var(--ds-tag-success-border);
}

.ds-tag--warning {
  background-color: var(--ds-tag-warning-bg);
  color: var(--ds-tag-warning-color);
  border-color: var(--ds-tag-warning-border);
}

.ds-tag--error {
  background-color: var(--ds-tag-error-bg);
  color: var(--ds-tag-error-color);
  border-color: var(--ds-tag-error-border);
}

/* =============================================================================
   AVATAR - .ds-avatar
   ============================================================================= */

.ds-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--ds-avatar-md-size);
  height: var(--ds-avatar-md-size);
  font-size: var(--ds-avatar-md-font-size);
  background-color: var(--ds-avatar-default-bg);
  color: var(--ds-avatar-default-color);
  border-radius: var(--ds-avatar-radius-circle);
  overflow: hidden;
  transition: var(--ds-avatar-transition);
}

.ds-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Avatar Sizes */
.ds-avatar--xs {
  width: var(--ds-avatar-xs-size);
  height: var(--ds-avatar-xs-size);
  font-size: var(--ds-avatar-xs-font-size);
}

.ds-avatar--sm {
  width: var(--ds-avatar-sm-size);
  height: var(--ds-avatar-sm-size);
  font-size: var(--ds-avatar-sm-font-size);
}

.ds-avatar--lg {
  width: var(--ds-avatar-lg-size);
  height: var(--ds-avatar-lg-size);
  font-size: var(--ds-avatar-lg-font-size);
}

.ds-avatar--xl {
  width: var(--ds-avatar-xl-size);
  height: var(--ds-avatar-xl-size);
  font-size: var(--ds-avatar-xl-font-size);
}

/* Avatar Shapes */
.ds-avatar--square {
  border-radius: var(--ds-avatar-radius-square);
}

.ds-avatar--rounded {
  border-radius: var(--ds-avatar-radius-rounded);
}

/* =============================================================================
   TOOLTIP - .ds-tooltip
   ============================================================================= */

.ds-tooltip {
  position: relative;
  display: inline-block;
}

.ds-tooltip__content {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  padding: var(--ds-tooltip-padding);
  background-color: var(--ds-tooltip-bg);
  color: var(--ds-tooltip-color);
  font-size: var(--ds-tooltip-font-size);
  border-radius: var(--ds-tooltip-radius);
  box-shadow: var(--ds-tooltip-shadow);
  white-space: nowrap;
  max-width: var(--ds-tooltip-max-width);
  z-index: var(--ds-z-index-tooltip);
  opacity: 0;
  visibility: hidden;
  transition: var(--ds-transition-fast);
  margin-bottom: 0.5rem;
}

.ds-tooltip:hover .ds-tooltip__content {
  opacity: 1;
  visibility: visible;
}

/* =============================================================================
   PROGRESS - .ds-progress
   ============================================================================= */

.ds-progress {
  width: 100%;
  height: var(--ds-progress-height);
  background-color: var(--ds-progress-bg);
  border-radius: var(--ds-progress-radius);
  overflow: hidden;
}

.ds-progress__bar {
  height: 100%;
  background-color: var(--ds-progress-fill-primary);
  border-radius: var(--ds-progress-radius);
  transition: width 0.3s ease;
}

.ds-progress__bar--success {
  background-color: var(--ds-progress-fill-success);
}

.ds-progress__bar--warning {
  background-color: var(--ds-progress-fill-warning);
}

.ds-progress__bar--error {
  background-color: var(--ds-progress-fill-error);
}

/* =============================================================================
   SPINNER - .ds-spinner
   ============================================================================= */

.ds-spinner {
  display: inline-block;
  width: var(--ds-spinner-md-size);
  height: var(--ds-spinner-md-size);
  border: 2px solid var(--ds-spinner-track);
  border-top-color: var(--ds-spinner-color);
  border-radius: 50%;
  animation: ds-spin 0.6s linear infinite;
}

.ds-spinner--sm {
  width: var(--ds-spinner-sm-size);
  height: var(--ds-spinner-sm-size);
}

.ds-spinner--lg {
  width: var(--ds-spinner-lg-size);
  height: var(--ds-spinner-lg-size);
}

.ds-spinner--xl {
  width: var(--ds-spinner-xl-size);
  height: var(--ds-spinner-xl-size);
}

/* =============================================================================
   DIVIDER - .ds-divider
   ============================================================================= */

.ds-divider {
  border: none;
  border-top: var(--ds-divider-width) solid var(--ds-divider-color);
  margin: var(--ds-divider-spacing) 0;
}

.ds-divider--vertical {
  border-top: none;
  border-left: var(--ds-divider-width) solid var(--ds-divider-color);
  height: 100%;
  margin: 0 var(--ds-divider-spacing);
  display: inline-block;
}

/* =============================================================================
   TABLE - .ds-table
   ============================================================================= */

.ds-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--ds-table-bg);
  border-radius: var(--ds-table-radius);
  overflow: hidden;
}

.ds-table th {
  background-color: var(--ds-table-header-bg);
  color: var(--ds-table-header-color);
  font-weight: var(--ds-table-header-font-weight);
  font-size: var(--ds-table-header-font-size);
  text-align: left;
}

.ds-table th,
.ds-table td {
  padding: var(--ds-table-cell-padding);
  border-bottom: 1px solid var(--ds-table-row-border);
}

.ds-table tbody tr {
  font-size: var(--ds-table-cell-font-size);
  transition: var(--ds-transition-fast);
}

.ds-table tbody tr:hover {
  background-color: var(--ds-table-row-bg-hover);
}

.ds-table--striped tbody tr:nth-child(even) {
  background-color: var(--ds-table-row-bg-striped);
}

/* =============================================================================
   SKELETON - .ds-skeleton
   ============================================================================= */

.ds-skeleton {
  background-color: var(--ds-skeleton-bg);
  border-radius: var(--ds-skeleton-radius);
  animation: ds-skeleton-pulse var(--ds-skeleton-animation-duration) ease-in-out infinite;
}

.ds-skeleton--text {
  height: 1em;
  width: 100%;
}

.ds-skeleton--circle {
  border-radius: 50%;
}

/* =============================================================================
   LINK - .ds-link
   ============================================================================= */

.ds-link {
  color: var(--ds-link-color);
  text-decoration: var(--ds-link-decoration);
  transition: var(--ds-transition-fast);
  cursor: pointer;
}

.ds-link:hover {
  color: var(--ds-link-color-hover);
  text-decoration: var(--ds-link-decoration-hover);
}

.ds-link:active {
  color: var(--ds-link-color-active);
}

/* =============================================================================
   ANIMATIONS
   ============================================================================= */

@keyframes ds-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes ds-skeleton-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* =============================================================================
   UTILITY CLASSES
   ============================================================================= */

/* Visually Hidden (for accessibility) */
.ds-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Focus Visible Ring */
.ds-focus-visible:focus-visible {
  outline: none;
  box-shadow: var(--ds-shadow-focus-ring);
}


