  color: var(--ds-color-neutral-500);
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='breadcrumb-link'] {
  color: var(--ds-color-primary-600);
  background: none;
  border: none;
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='breadcrumb-separator'] {
  color: var(--ds-color-neutral-400);
}

/* ---- back-button (rustic has no hover/focus paint — divergence preserved) ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='back-button'] {
  background: none;
  border: none;
  color: var(--ds-color-neutral-600);
  border-radius: var(--ds-radius-sm);
}

/* ---- subtitle ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='subtitle'] {
  color: var(--ds-color-neutral-500);
}

/* ---- status badge: rustic honors the arbitrary runtime `status.color`, which a
        static skin cannot bake. The element carries the color as two custom
        properties inline (only when set); the fallbacks are the neutral pill the
        factory used when no color was provided. ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='status-badge'] {
  display: inline-block;
  padding: 0.125rem 0.5rem;
  border-radius: var(--ds-radius-full, 9999px);
  font-size: var(--ds-font-size-xs);
  font-weight: 500;
  background: var(--ds-detail-panel-status-bg, var(--ds-color-neutral-200));
  color: var(--ds-detail-panel-status-fg, var(--ds-color-neutral-700));
}

/* ---- action-button: per-variant base + ghost/default hover + all-variant focus.
        The JSX hover guard was `!disabled && (variant==='ghost' || !variant)`; a
        button with no explicit variant renders `data-variant='default'`, so the
        default/ghost hover selectors cover it. Native `disabled` covers
        disabled||loading. ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='default'] {
  border: 1px solid var(--ds-color-neutral-300);
  background: var(--ds-color-neutral-0, #fff);
  color: var(--ds-color-neutral-700);
  border-radius: var(--ds-radius-md);
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='primary'] {
  border: 1px solid var(--ds-color-primary-600);
  background: var(--ds-color-primary-600);
  color: var(--ds-color-text-on-primary);
  border-radius: var(--ds-radius-md);
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='danger'] {
  border: 1px solid var(--ds-color-error-600, #dc2626);
  background: var(--ds-color-error-600, #dc2626);
  color: var(--ds-color-text-on-primary);
  border-radius: var(--ds-radius-md);
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='ghost'] {
  border: 1px solid transparent;
  background: transparent;
  color: var(--ds-color-neutral-700);
  border-radius: var(--ds-radius-md);
}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='ghost']:hover:not(:disabled),
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button'][data-variant='default']:hover:not(:disabled) {
