}
.ds-pattern-detail-panel.ds-engine-rustic [data-part='action-button']:focus {
  box-shadow: 0 0 0 2px var(--ds-color-bg-primary, #fff), 0 0 0 4px var(--ds-color-primary-400, #818cf8);
}

/* ---- sidebar panel ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='sidebar'][data-part='sidebar'] {
