/* ---- footer top divider ---- */
.ds-pattern-detail-panel.ds-engine-rustic [data-part='footer'][data-part='footer'] {
  border-top: 1px var(--ds-divider-style, solid) var(--ds-divider-color, var(--ds-color-neutral-200));
