/* ---- loading skeleton parts ---- */
.ds-pattern-data-table.ds-engine-modern [data-part='skeleton-header'] {
  background: var(--ds-table-header-bg, var(--ds-surface-inset, var(--ds-surface-panel)));
}
.ds-pattern-data-table.ds-engine-modern [data-part='skeleton-header'][data-part='skeleton-header'] {
  border-bottom: 1px solid var(--ds-table-border, var(--ds-color-border-subtle));
}
.ds-pattern-data-table.ds-engine-modern [data-part='skeleton-header-col'] {
  border-radius: var(--ds-radius-sm, 6px);
  background: var(--ds-color-border-subtle);
}
.ds-pattern-data-table.ds-engine-modern [data-part='skeleton-row'][data-divider='true'] {
  border-bottom: 1px solid var(--ds-table-row-border, var(--ds-color-border-subtle));
}
.ds-pattern-data-table.ds-engine-modern [data-part='skeleton-cell'] {
  border-radius: var(--ds-radius-sm, 6px);
  background: color-mix(in srgb, var(--ds-color-text-primary) 6%, transparent);
