/* ---- empty state (container tint + default icon-tile/title/description) ---- */
.ds-pattern-data-table.ds-engine-modern [data-part='empty-state'] {
  color: var(--ds-color-text-muted);
}
.ds-pattern-data-table.ds-engine-modern [data-part='empty-icon-tile'] {
  border-radius: var(--ds-radius-lg, 12px);
  background: color-mix(in srgb, var(--ds-color-text-primary) 4%, transparent);
