/* ---- thead sticky shadow (position/top/z-index stay inline; only the shadow
        the `stickyHeader` branch painted moves here) ---- */
.ds-pattern-data-table.ds-engine-modern [data-part='table-head'][data-sticky='true'] {
  box-shadow: var(--ds-elevation-1);
}

/* ---- header row ---- */
.ds-pattern-data-table.ds-engine-modern [data-part='header-row'] {
  background: var(--ds-table-header-bg, color-mix(in srgb, var(--ds-surface-inset, var(--ds-surface-panel)) 92%, var(--ds-color-text-primary) 8%));
