.ds-input-number.ds-input-number--rustic[data-part='root'][data-part='root']:focus:not([data-status='error']):not([data-status='warning']) {
  border: 1px solid var(--ds-inputnumber-border-focus);
}
.ds-input-number.ds-input-number--rustic[data-part='root'][data-part='root'][data-status='warning'] {
  border: 1px solid var(--ds-inputnumber-warning-border);
