  background-color: var(--ds-color-neutral-100, #f5f5f5);
}
.ds-password-input.ds-password-input--rustic[data-part='root']:not([data-variant='filled']) {
  background-color: transparent;
}

/* border-radius: flushed/unstyled square, everything else md. */
.ds-password-input.ds-password-input--rustic[data-part='root']:not([data-variant='flushed']):not([data-variant='unstyled']) {
  border-radius: var(--ds-radius-md, 8px);
}
