/* ---- preview-modal / preview-close-button / progress-track: identical in
        both Upload and Dragger subtrees (declared once, used by both). ---- */
.ds-upload.ds-upload--modern [data-part='preview-modal'],
.ds-upload-dragger.ds-upload-dragger--modern [data-part='preview-modal'] {
  background: var(--ds-upload-preview-backdrop);
}
.ds-upload.ds-upload--modern [data-part='preview-close-button'],
.ds-upload-dragger.ds-upload-dragger--modern [data-part='preview-close-button'] {
  background: var(--ds-color-error);
  color: var(--ds-color-text-on-primary);
  border-radius: 50%;
  border: none;
}
.ds-upload.ds-upload--modern [data-part='progress-track'],
.ds-upload-dragger.ds-upload-dragger--modern [data-part='progress-track'] {
  background: var(--ds-surface-panel);
}
/* progress-bar fill: a runtime `strokeColor` (plain color or computed gradient)
   carried via the uncounted custom property `--ds-upload-progress-fill`; only
   the runtime `width` stays inline. */
.ds-upload.ds-upload--modern [data-part='progress-bar'],
.ds-upload-dragger.ds-upload-dragger--modern [data-part='progress-bar'] {
  background: var(--ds-upload-progress-fill);
}

/* ---- file-item-overlay: only rendered by the picture-card/picture-circle
        branches, so no listType scope is needed -- the data-part itself is
        variant-exclusive. ---- */
.ds-upload.ds-upload--modern [data-part='file-item-overlay'],
.ds-upload-dragger.ds-upload-dragger--modern [data-part='file-item-overlay'] {
  background: var(--ds-upload-preview-overlay);
}

/* ---- file-item base: circle/picture/text share one background; card is the
        odd one out (own background + radius + border). ---- */
.ds-upload.ds-upload--modern:not(.ds-upload--picture-card) [data-part='file-item'],
.ds-upload-dragger.ds-upload-dragger--modern:not(.ds-upload-dragger--picture-card) [data-part='file-item'] {
  background: var(--ds-surface-inset);
}

.ds-upload.ds-upload--modern.ds-upload--picture-card [data-part='file-item'],
.ds-upload-dragger.ds-upload-dragger--modern.ds-upload-dragger--picture-card [data-part='file-item'] {
  background: var(--ds-color-bg-secondary);
  border-radius: var(--ds-upload-file-radius, 6px);
  border: 1px solid var(--ds-color-border);
