.ds-upload.ds-upload--modern.ds-upload--picture [data-part='file-item'] > div:has(svg) svg,
.ds-upload-dragger.ds-upload-dragger--modern.ds-upload-dragger--picture [data-part='file-item'] > div:has(svg) svg {
