.ds-upload-dragger.ds-upload-dragger--modern [data-part='dropzone'] svg {
  color: var(--ds-color-text-secondary);
}
.ds-upload-dragger.ds-upload-dragger--modern [data-part='dropzone'] p {
  color: var(--ds-color-text-secondary);
