/* ---------------------------------------------------------------------
   Panel (portal, standalone) -- shared by TimePickerBase and TimeRangePicker
   --------------------------------------------------------------------- */

.rottay-timepicker__panel {
  background: var(--ds-color-bg-elevated);
  border-radius: var(--ds-radius-lg, 12px);
