}
.rottay-timepicker__panel.rottay-timepicker__panel[data-part='panel'][data-part='panel'] {
  border: 1px solid var(--ds-color-border);
}

/* column divider: a bare `<div>` with no data-part, always the immediate next
   sibling of a `[data-part='time-column']` in both the 2-column and 3-column
   (showSeconds) layouts. */
.rottay-timepicker__panel [data-part='time-column'] + div {
  background: var(--ds-color-border);
}

.rottay-timepicker__panel.rottay-timepicker__panel [data-part='header'][data-part='header'] {
  border-bottom: 1px solid var(--ds-color-border);
}
/* column-label spans (Hr/Min/Sec + the two zero-width spacer spans) share one
   color; all are bare `<span>` children of header, no individual data-part. */
.rottay-timepicker__panel [data-part='header'] > span {
  color: var(--ds-color-text-muted);
}

.rottay-timepicker__panel [data-part='time-option'] {
  border-radius: var(--ds-radius-md, 8px);
