}
.rottay-datepicker-range.rottay-datepicker-range--rustic [data-part='trigger-input']:disabled {
  background-color: var(--ds-datepicker-bg-disabled, var(--ds-color-bg-secondary));
}
.rottay-datepicker-range.rottay-datepicker-range--rustic [data-part='trigger-input'][data-active='true'] {
  box-shadow: var(--ds-datepicker-shadow-focus, 0 0 0 2px var(--ds-color-primary-100));
}

.rottay-datepicker-range.rottay-datepicker-range--rustic [data-part='trigger-input'][data-part='trigger-input'] {
  border: 1px solid var(--ds-datepicker-border, var(--ds-color-border));
}
.rottay-datepicker-range.rottay-datepicker-range--rustic:not(.rottay-datepicker-range--error):not(.rottay-datepicker-range--warning) [data-part='trigger-input'][data-part='trigger-input'][data-active='true'] {
  border: 1px solid var(--ds-datepicker-border-focus, var(--ds-color-primary-500));
}
.rottay-datepicker-range.rottay-datepicker-range--rustic.rottay-datepicker-range--error [data-part='trigger-input'][data-part='trigger-input'] {
  border: 1px solid var(--ds-datepicker-error-border, var(--ds-color-error));
}
.rottay-datepicker-range.rottay-datepicker-range--rustic.rottay-datepicker-range--warning [data-part='trigger-input'][data-part='trigger-input'] {
  border: 1px solid var(--ds-datepicker-warning-border, var(--ds-color-warning));
}

.rottay-datepicker-range.rottay-datepicker-range--rustic [data-part='separator'] {
  color: var(--ds-datepicker-separator-color, var(--ds-color-text-tertiary));
