/* ---------------------------------------------------------------------
   Panel (portal, standalone) -- shared by DatePickerBase and RangePicker,
   all three modes (month/year/date).
   --------------------------------------------------------------------- */

.rottay-datepicker-panel.rottay-datepicker-panel--rustic {
  background-color: var(--ds-datepicker-panel-bg, var(--ds-color-bg-elevated));
  border-radius: var(--ds-datepicker-panel-radius, 8px);
