/* ---- tree node row ---- */
.rottay-treeselect__dropdown[data-part='dropdown'] [data-part='option'] {
  background-color: transparent;
  border-radius: var(--ds-treeselect-node-radius);
}
.rottay-treeselect__dropdown[data-part='dropdown'] [data-part='option'][data-part='option'] {
  border-left: 3px solid transparent;
}
.rottay-treeselect__dropdown[data-part='dropdown'] [data-part='option']:hover:not([data-selected='true']):not([data-disabled='true']) {
  background-color: var(--ds-treeselect-node-bg-hover);
}
.rottay-treeselect__dropdown[data-part='dropdown'] [data-part='option'][data-selected='true'] {
