.rottay-treeselect__dropdown[data-part='dropdown'] [data-part='tree-list']:not([data-tree-line='true'])[data-nested='true'] {
  border-left: 1px solid var(--ds-color-border-secondary, rgba(0, 0, 0, 0.06));
