.rottay-cascader.rottay-cascader--rustic[data-part='trigger'] [data-part='placeholder'] {
  color: var(--ds-cascader-placeholder-color);
}

.rottay-cascader.rottay-cascader--rustic[data-part='trigger'] [data-part='clear-button'] {
