.rottay-progress-shell.rottay-progress-shell--modern[data-status='success'] [data-part='fill'] {
  accent-color: var(--ds-progress-arc-color, var(--ds-color-success));
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='error'] [data-part='fill'] {
  accent-color: var(--ds-progress-arc-color, var(--ds-color-error));
}
.rottay-progress-shell.rottay-progress-shell--modern[data-status='active'] [data-part='fill'] {
  accent-color: var(--ds-progress-arc-color, var(--ds-color-primary));
