/* ---- the joined seam: every button but `next` drops its right edge. ---- */
.rottay-pagination--modern[data-part='root'] [data-part='pagination-nav-button'][data-direction='prev'][data-part='pagination-nav-button'],
.rottay-pagination--modern[data-part='root'] [data-part='pagination-page-button'][data-part='pagination-page-button'],
.rottay-pagination--modern[data-part='root'] [data-part='ellipsis'][data-part='ellipsis'] {
  border-right: none;
