/* ---- the outer corners round; the inner seams stay square. ---- */
.rottay-pagination--modern[data-part='root'] [data-part='pagination-nav-button'][data-direction='prev'] {
  border-radius: var(--ds-radius-md) 0 0 var(--ds-radius-md);
