.rottay-popover--modern[data-part='trigger'] [data-part='title'][data-part='title'] {
  border-bottom: 1px solid var(--ds-color-border);
}

/* ---- arrow: this engine's arrow has NO box-shadow (rustic's does). Preserved. ---- */
.rottay-popover--modern[data-part='trigger'] [data-part='arrow'] {
  background: var(--ds-surface-card);
