.rottay-calendar.rottay-calendar--modern[data-part='root'] > [data-part='header'] > div > [data-part='mode-toggle'][data-active='true'] {
  background: var(--ds-color-primary);
  color: var(--ds-color-text-on-primary);
}

/* ---- weekday column headers ---- */
.rottay-calendar.rottay-calendar--modern[data-part='root'] > div > [data-part='weekday-header'] {
  color: var(--ds-color-text-secondary);
}

/* ---- cells (one rule set serves the month grid and the year grid: their paint
        is identical, only their geometry differs). ---- */
.rottay-calendar.rottay-calendar--modern[data-part='root'] > [data-part='grid'] > [data-part='cell'][data-selected='true'] {
  background: var(--ds-color-primary);
