.rottay-divider.rottay-divider--rustic[data-part='root'][data-orientation='horizontal'] [data-part='line-after'] {
  border-top: var(--ds-divider-line, 1px solid var(--ds-divider-color, #d9d9d9));
  border-left: none;
  border-right: none;
  border-bottom: none;
}
.rottay-divider.rottay-divider--rustic[data-part='root'][data-orientation='vertical'] [data-part='line-before'],
.rottay-divider.rottay-divider--rustic[data-part='root'][data-orientation='vertical'] [data-part='line-after'] {
  border-left: var(--ds-divider-line, 1px solid var(--ds-divider-color, #d9d9d9));
  border-top: none;
  border-right: none;
  border-bottom: none;
}

/* ---- line: plain divider, merged onto the root itself (was the simple-
        divider return path's `{ ...containerStyle, ...lineStyle }`). Gated
        to `data-with-text='false'` -- the with-text root never carries this
        channel. ---- */
.rottay-divider.rottay-divider--rustic[data-part='root'][data-orientation='horizontal'][data-with-text='false'] {
  border-top: var(--ds-divider-line, 1px solid var(--ds-divider-color, #d9d9d9));
  border-left: none;
  border-right: none;
  border-bottom: none;
