.rottay-image.rottay-image--rustic[data-part='root'][data-part='root'][data-shadow='true'] {
  box-shadow: var(--ds-image-shadow, 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06));
}

/* ---- the image itself ---- */
.rottay-image.rottay-image--rustic > [data-part='img'] {
