  background: var(--ds-list-skeleton-bg, var(--ds-color-bg-tertiary));
  border-radius: 4px;
}

/* header + footer separators, bordered mode only */
.rottay-list.rottay-list--rustic[data-part='root'][data-bordered='true'] > [data-part='header'] {
  border-bottom: 1px solid var(--ds-list-border-color, var(--ds-color-border));
}
