}

/* ---- value: trend color. The unqualified rule carries the `default` value
        because the lookup it replaces fell back to `default` for an
        unrecognised trend; `valueStyle` still wins as inline. ---- */
.rottay-statistic.rottay-statistic--rustic[data-part='root'] > [data-part='value'] {
  color: var(--ds-statistic-value-color, var(--ds-color-text-primary));
}
.rottay-statistic.rottay-statistic--rustic[data-part='root'] > [data-part='value'][data-trend='positive'] {
  color: var(--ds-statistic-positive-color, var(--ds-color-success));
}
.rottay-statistic.rottay-statistic--rustic[data-part='root'] > [data-part='value'][data-trend='negative'] {
  color: var(--ds-statistic-negative-color, var(--ds-color-error));
}
.rottay-statistic.rottay-statistic--rustic[data-part='root'] > [data-part='value'][data-trend='warning'] {
  color: var(--ds-statistic-warning-color, var(--ds-color-warning));
