}
.rottay-timeline.rottay-timeline--modern[data-part='root'] > [data-part='item'][data-pending='true'] > [data-part='body'] > [data-part='spinner'] {
  border: 2px solid var(--ds-color-border);
  border-top-color: var(--ds-timeline-pending-dot-color, var(--ds-color-primary));
  border-radius: 50%;
