/* ---- dot: shared disc, then the two branches of a caller-supplied dot ---- */
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'] > [data-part='dot'] {
  border-radius: 50%;
}
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'] > [data-part='dot'][data-custom-dot='false'] {
  background-color: var(--ds-timeline-dot-color);
  border: var(--ds-timeline-dot-border-width) solid white;
  box-shadow: 0 0 0 var(--ds-timeline-dot-border-width) var(--ds-timeline-dot-color);
}
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'] > [data-part='dot'][data-custom-dot='true'] {
  background-color: transparent;
  border: none;
  box-shadow: none;
}

/* ---- per-item label ---- */
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'] > [data-part='label'] {
  color: var(--ds-timeline-label-color, #999);
}

/* ---- pending row: dot fill (animation stays inline) + muted body ---- */
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'][data-pending='true'] > [data-part='dot'] {
  background-color: var(--ds-timeline-pending-dot-color, #e8e8e8);
}
.rottay-timeline.rottay-timeline--rustic[data-part='root'] > [data-part='item'][data-pending='true'] > [data-part='body'] {
  color: var(--ds-timeline-pending-color, #999);
}

/**
 * Modern Tooltip skin (WO-SKIN-05 checkpoint D2).
 *
 * DELIBERATELY UNLAYERED (P-47): every `rottay-*` layer sorts before Tailwind's
 * base layer, so a layered rule loses to preflight regardless of specificity.
 * Unlayered outranks preflight and still yields to a caller's inline `style`.
 *
 * PORTALED, THEREFORE STANDALONE. The bubble mounts via
