/* title (Box as h2) ------------------------------------------------------------- */

.ds-structure.ds-collection-header [data-part='title'] {
  color: var(--ds-color-text-primary);
}
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='dotted'] {
  color: transparent;
}
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='display'] {
  text-shadow: 0 0 24px color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 12%, transparent);
}

/* dotted-title glyph-clip recipe: the counted background and filter move here; the
   uncounted -webkit-background-clip / -webkit-text-fill-color / -webkit-text-stroke
   stay inline (leave non-counted paint in place). background-position + clip are
   constant across the three dotted branches; the image/size/filter branch on
   compact vs editorial-tech vs default. */
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='dotted'] {
  background-position: 0 0, 0 0;
  background-clip: text, text;
}
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='dotted'][data-compact-layout='true'] {
  background-image:
    radial-gradient(circle at 1px 1px, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 76%, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 24%) 0 0.45px, transparent 0.65px),
    linear-gradient(180deg, color-mix(in srgb, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 60%, var(--ds-collection-header-display-color, var(--ds-color-primary)) 40%) 0%, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 52%, transparent) 100%);
  background-size: 4px 4px, 100% 100%;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 8%, transparent));
}
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='dotted'][data-compact-layout='false'][data-editorial-tech='true'] {
  background-image:
    radial-gradient(circle at 1.35px 1.35px, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 78%, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 22%) 0 0.56px, transparent 0.72px),
    linear-gradient(180deg, color-mix(in srgb, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 58%, var(--ds-collection-header-display-color, var(--ds-color-primary)) 42%) 0%, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 68%, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 20%) 54%, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 42%, transparent) 100%);
  background-size: 5.2px 5.2px, 100% 100%;
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 10%, transparent));
}
.ds-structure.ds-collection-header [data-part='title'][data-title-treatment='dotted'][data-compact-layout='false'][data-editorial-tech='false'] {
  background-image:
    radial-gradient(circle, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 82%, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 18%) 0 1px, transparent 1.2px),
    linear-gradient(180deg, color-mix(in srgb, var(--ds-collection-header-display-shade, var(--ds-color-text-primary)) 58%, var(--ds-collection-header-display-color, var(--ds-color-primary)) 42%) 0%, color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 56%, transparent) 100%);
  background-size: 6px 6px, 100% 100%;
  filter: drop-shadow(0 0 18px color-mix(in srgb, var(--ds-collection-header-display-color, var(--ds-color-primary)) 12%, transparent));
}

/* subtitle divider + editorial-tech rule + title accent bar --------------------- */

.ds-structure.ds-collection-header [data-part='subtitle-divider'] {
  background: linear-gradient(90deg, color-mix(in srgb, var(--ds-color-border-subtle) 82%, transparent) 0%, color-mix(in srgb, var(--ds-color-border-subtle) 34%, transparent) 100%);
}
.ds-structure.ds-collection-header [data-part='editorial-tech-rule'] {
  background: linear-gradient(90deg, color-mix(in srgb, var(--ds-color-border-subtle) 76%, transparent) 0%, color-mix(in srgb, var(--ds-color-border-subtle) 40%, transparent) 40%, color-mix(in srgb, var(--ds-color-border-subtle) 18%, transparent) 72%, transparent 100%);
}
.ds-structure.ds-collection-header [data-part='title-accent'] {
  border-radius: 999px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-color-primary) 48%, transparent) 0%, color-mix(in srgb, var(--ds-color-primary) 12%, transparent) 100%);
}
/* subtitle-row: the default-branch subtitle wrapper. The repeated data-part buys
   (0,4,0) so its top border clears the tenant border-color floor at (0,3,1). */
.ds-structure.ds-collection-header [data-part='subtitle-row'][data-part='subtitle-row'] {
  border-top: 1px solid color-mix(in srgb, var(--ds-color-border-subtle) 72%, transparent);
}

/* subtitle (Text) — two variants ------------------------------------------------ */

.ds-structure.ds-collection-header [data-part='subtitle'][data-part='subtitle'][data-part='subtitle'][data-variant='editorial-tech'] {
  color: color-mix(in srgb, var(--ds-color-text-secondary) 88%, var(--ds-color-primary) 12%);
}
.ds-structure.ds-collection-header [data-part='subtitle'][data-part='subtitle'][data-part='subtitle'][data-variant='default'] {
  color: var(--ds-color-text-secondary);
}

/* quick-actions pill container -------------------------------------------------- */

.ds-structure.ds-collection-header [data-part='quick-actions'] {
  border-radius: var(--ds-radius-md, 8px);
}
.ds-structure.ds-collection-header [data-part='quick-actions'][data-part='quick-actions'] {
  border: 1px solid var(--ds-color-border-subtle);
}
.ds-structure.ds-collection-header [data-part='quick-actions'][data-embedded='true'][data-editorial-tech='true'] {
  background: color-mix(in srgb, var(--ds-surface-panel) 68%, transparent);
  box-shadow: 0 8px 18px color-mix(in srgb, var(--ds-color-primary) 10%, transparent), inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 52%, transparent);
}
.ds-structure.ds-collection-header [data-part='quick-actions'][data-embedded='true'][data-editorial-tech='false'] {
  background: color-mix(in srgb, var(--ds-surface-panel) 76%, transparent);
  box-shadow: 0 10px 24px color-mix(in srgb, var(--ds-color-primary) 12%, transparent), inset 0 1px 0 color-mix(in srgb, var(--ds-color-bg-elevated) 58%, transparent);
}
.ds-structure.ds-collection-header [data-part='quick-actions'][data-embedded='false'] {
  background: var(--ds-surface-panel);
  box-shadow: var(--ds-elevation-1);
}

/* quick-action Button — BEM classes repeated to (0,6,0) to override button.css --- */

.ds-structure.ds-collection-header .ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action {
  border-radius: 999px;
}
.ds-structure.ds-collection-header .ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action--primary {
  box-shadow: var(--ds-elevation-1);
}
.ds-structure.ds-collection-header .ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action--secondary,
.ds-structure.ds-collection-header .ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action.ds-collection-header__quick-action--default {
  box-shadow: none;
}

/* shortcuts label + shortcut pills (Box; embedded keyed off the ROOT ancestor) -- */

.ds-structure.ds-collection-header [data-part='shortcuts-label'] {
  border-radius: 999px;
  color: var(--ds-color-text-muted);
}
.ds-structure.ds-collection-header [data-part='shortcuts-label'][data-part='shortcuts-label'] {
  border: 1px solid var(--ds-color-border-subtle);
}
.ds-structure.ds-collection-header[data-embedded='true'] [data-part='shortcuts-label'] {
  background: color-mix(in srgb, var(--ds-surface-panel) 68%, transparent);
}
.ds-structure.ds-collection-header[data-embedded='false'] [data-part='shortcuts-label'] {
  background: var(--ds-surface-panel);
}

.ds-structure.ds-collection-header [data-part='shortcut-pill'] {
  border-radius: 999px;
  color: var(--ds-color-text-muted);
}
.ds-structure.ds-collection-header [data-part='shortcut-pill'][data-part='shortcut-pill'] {
  border: 1px solid var(--ds-color-border-subtle);
}
.ds-structure.ds-collection-header[data-embedded='true'] [data-part='shortcut-pill'] {
  background: color-mix(in srgb, var(--ds-surface-panel) 66%, transparent);
}
.ds-structure.ds-collection-header[data-embedded='false'] [data-part='shortcut-pill'] {
  background: var(--ds-surface-panel);
}

/**
 * DashboardHeader skin — engine-agnostic, DELIBERATELY UNLAYERED (P-47).
 * Home: tokens/css/components/skin/dashboard-header.css — DashboardHeader renders
 * one DOM tree under every engine (no engines/ split), so it has a single skin.
 *
 * SCOPE ROOT is the header's outer element, which carries the pair
 * `ds-structure ds-dashboard-header` + `data-part='root'` + `data-compact`
 * (both the compact and full renders share the class pair and part).
 *
 * SPECIFICITY (P-48): the Platform-only Rottay artifact ships an unlayered
 * `html[data-tenant]:not([data-theme]):not(.light) *` at (0,3,1) that sets
 * `border-color` on every element. A rule that paints a border COLOR must reach
 * (0,4,0): two root classes (0,2,0) + a `data-part` REPEATED or a real contract
 * attribute (`data-compact`) for the remaining (0,2,0). Non-border paint wins
 * unlayered at (0,3,0).
 *
 * Text color is a special case: the modern/rustic typography skins paint every
 * `Text` at `.rottay-typography.rottay-typography--<engine>.rottay-typography--<engine>[data-color='…']`
 * = (0,4,0), unlayered. A color rule on a composed `Text` must therefore exceed
 * (0,4,0); it buys (0,5,0) from the two root classes + the target `data-part`
 * repeated three times. Box/icon color has no such competitor and wins at (0,3,0)
 * (the icon inherits `currentColor` from the Box the rule paints).
 *
 * STATE: `STATUS_COLORS[state]` and the change-direction ternary are
 * STATE-SELECTED over static tokens, so each becomes a rule keyed on the stamped
 * `data-state` / `data-direction`. `data-compact` selects between the two header
 * shells.
 */

/* status dot — pill background is the status colour at 12% -------------------- */

.ds-structure.ds-dashboard-header [data-part='status-dot'] {
  border-radius: var(--ds-radius-full, 9999px);
}
.ds-structure.ds-dashboard-header [data-part='status-dot'][data-state='live'],
.ds-structure.ds-dashboard-header [data-part='status-dot'][data-state='connected'] {
  background: color-mix(in srgb, var(--ds-color-success) 12%, transparent);
}
.ds-structure.ds-dashboard-header [data-part='status-dot'][data-state='syncing'],
.ds-structure.ds-dashboard-header [data-part='status-dot'][data-state='warning'] {
  background: color-mix(in srgb, var(--ds-color-warning) 12%, transparent);
}
.ds-structure.ds-dashboard-header [data-part='status-dot'][data-state='offline'] {
  background: color-mix(in srgb, var(--ds-color-error) 12%, transparent);
}

/* status dot glyph — solid status colour ------------------------------------- */

.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'] {
  border-radius: 50%;
}
.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'][data-state='live'],
.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'][data-state='connected'] {
  background: var(--ds-color-success);
}
.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'][data-state='syncing'],
.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'][data-state='warning'] {
  background: var(--ds-color-warning);
}
.ds-structure.ds-dashboard-header [data-part='status-dot-glyph'][data-state='offline'] {
  background: var(--ds-color-error);
}

/* status dot text — Text, needs (0,5,0) to beat the typography skin ----------- */

.ds-structure.ds-dashboard-header [data-part='status-dot-text'][data-part='status-dot-text'][data-part='status-dot-text'][data-state='live'],
.ds-structure.ds-dashboard-header [data-part='status-dot-text'][data-part='status-dot-text'][data-part='status-dot-text'][data-state='connected'] {
  color: var(--ds-color-success);
}
.ds-structure.ds-dashboard-header [data-part='status-dot-text'][data-part='status-dot-text'][data-part='status-dot-text'][data-state='syncing'],
.ds-structure.ds-dashboard-header [data-part='status-dot-text'][data-part='status-dot-text'][data-part='status-dot-text'][data-state='warning'] {
  color: var(--ds-color-warning);
}
.ds-structure.ds-dashboard-header [data-part='status-dot-text'][data-part='status-dot-text'][data-part='status-dot-text'][data-state='offline'] {
  color: var(--ds-color-error);
}

/* metric chip ---------------------------------------------------------------- */

.ds-structure.ds-dashboard-header [data-part='metric-chip'] {
  border-radius: var(--ds-radius-md, 8px);
  background: var(--ds-color-bg-secondary);
}
.ds-structure.ds-dashboard-header [data-part='metric-chip'][data-part='metric-chip'] {
  border: 1px solid var(--ds-color-border-secondary);
}

.ds-structure.ds-dashboard-header [data-part='metric-chip-icon'] {
  color: var(--ds-color-text-muted);
}

/* metric chip change — Text keyed on direction, (0,5,0) + data-direction ------ */

.ds-structure.ds-dashboard-header [data-part='metric-chip-change'][data-part='metric-chip-change'][data-part='metric-chip-change'][data-direction='up'] {
  color: var(--ds-color-success);
}
.ds-structure.ds-dashboard-header [data-part='metric-chip-change'][data-part='metric-chip-change'][data-part='metric-chip-change'][data-direction='down'] {
  color: var(--ds-color-error);
}
.ds-structure.ds-dashboard-header [data-part='metric-chip-change'][data-part='metric-chip-change'][data-part='metric-chip-change'][data-direction='flat'] {
  color: var(--ds-color-text-muted);
}

/* leading icon (compact + full share data-part='icon') ----------------------- */

.ds-structure.ds-dashboard-header [data-part='icon'] {
  color: var(--ds-color-text-muted);
}

/* header shells — compact vs full, keyed on data-compact --------------------- */

.ds-structure.ds-dashboard-header [data-part='root'][data-compact='true'] {
  border-bottom: 1px solid var(--ds-color-border-secondary);
}
.ds-structure.ds-dashboard-header [data-part='root'][data-compact='false'] {
  background: var(--ds-color-bg-primary);
  border-bottom: 1px solid var(--ds-color-border-secondary);
}

/**
 * ActivityTicker skin — engine-agnostic, DELIBERATELY UNLAYERED (P-47).
 * Home: tokens/css/components/skin/activity-ticker.css — ActivityTicker renders
 * one DOM tree under every engine (no engines/ split), so it has a single skin.
 *
 * SCOPE ROOT carries the single class `ds-activity-ticker` + `data-part='root'`.
 * The kit's "two root classes" budget is bought here by REPEATING the one class
 * (`.ds-activity-ticker.ds-activity-ticker` = 0,2,0) since the pre-step minted a
 * single scope class, not a class pair.
 *
 * SPECIFICITY (P-48): the Platform-only Rottay artifact ships an unlayered
 * `html[data-tenant]:not([data-theme]):not(.light) *` at (0,3,1) that sets
 * `border-color` on every element. A rule that paints a border COLOR must reach
 * (0,4,0): the repeated scope class (0,2,0) + the target `data-part` REPEATED
 * (0,2,0). Non-border paint wins unlayered at (0,3,0). A `Text` color must beat
 * the typography skin (0,4,0), so it buys (0,5,0) from the repeated scope class
 * + the data-part repeated three times.
 *
 * ICON COLOR: the Bell / ExternalLink / Chevron / per-item icons carry no
 * data-part (raw lucide nodes). Their color is painted on the nearest stamped
 * ancestor Box and inherited through `currentColor` (the dashboard-header
 * precedent); every Text sibling carries its own (0,5,0) color rule, so none
 * inherits the icon color by accident.
 *
 * STATE: `TYPE_CONFIG[type].gradient` and the `"var(--ds-color-" + type + ...)"`
 * string-concat sites are STATE-SELECTED over the bounded 5-value
 * `ActivityItem["type"]` enum, so both become rules keyed on the stamped
 * `data-type`. `data-active` selects the active pagination dot. The unread-badge
 * count text is a literal `white` in source and is transcribed verbatim.
 *
 * The `<style>` block co-located in the TSX is left intact (entrance/keyframe
 * animation, scroll chrome, and `:hover` transform/box-shadow that was never
 * suppressed by an inline paint). Its `:hover` background/border-color rules sit
 * at (0,2,0) and were already suppressed by the former inline paint; the rest
 * rules below sit at (0,3,0)/(0,4,0) and preserve that suppression byte-exact.
 */

/* root + header ------------------------------------------------------------- */

.ds-activity-ticker.ds-activity-ticker[data-part='root'] {
  background: var(--ds-color-bg-secondary);
}
.ds-activity-ticker.ds-activity-ticker[data-part='root'][data-part='root'] {
  border: 1px solid var(--ds-color-border-secondary);
}
.ds-activity-ticker.ds-activity-ticker [data-part='header'][data-part='header'] {
  border-bottom: 1px solid var(--ds-color-border-secondary);
}

/* bell box + badge ---------------------------------------------------------- */

.ds-activity-ticker.ds-activity-ticker [data-part='bell-box'] {
  background: linear-gradient(135deg, var(--ds-color-primary-100), var(--ds-color-secondary-100));
  color: var(--ds-color-primary);
}
.ds-activity-ticker.ds-activity-ticker [data-part='bell-box'][data-part='bell-box'] {
  border: 1px solid var(--ds-color-primary-200);
}
.ds-activity-ticker.ds-activity-ticker [data-part='badge'] {
  border-radius: 50%;
  background: var(--ds-color-error);
}
.ds-activity-ticker.ds-activity-ticker [data-part='badge'][data-part='badge'] {
  border: 2px solid var(--ds-color-bg-secondary);
}
.ds-activity-ticker.ds-activity-ticker [data-part='badge-count'][data-part='badge-count'][data-part='badge-count'] {
  color: white;
}

/* title + live indicator ---------------------------------------------------- */

.ds-activity-ticker.ds-activity-ticker [data-part='title'][data-part='title'][data-part='title'] {
  color: var(--ds-color-text-primary);
}
.ds-activity-ticker.ds-activity-ticker [data-part='live-dot'] {
  border-radius: 50%;
  background: var(--ds-color-success);
}
.ds-activity-ticker.ds-activity-ticker [data-part='live-label'][data-part='live-label'][data-part='live-label'] {
  color: var(--ds-color-success);
}

/* view-all pill ------------------------------------------------------------- */

.ds-activity-ticker.ds-activity-ticker [data-part='view-all-link'] {
  background: var(--ds-color-primary-100);
  color: var(--ds-color-primary);
}
.ds-activity-ticker.ds-activity-ticker [data-part='view-all-link'][data-part='view-all-link'] {
  border: 1px solid var(--ds-color-primary-200);
}
.ds-activity-ticker.ds-activity-ticker [data-part='view-all-label'][data-part='view-all-label'][data-part='view-all-label'] {
  color: var(--ds-color-primary);
}

/* ticker body --------------------------------------------------------------- */

.ds-activity-ticker.ds-activity-ticker [data-part='ticker-body'] {
  background: linear-gradient(180deg, var(--ds-color-bg-primary) 0%, var(--ds-color-neutral-50) 100%);
}
.ds-activity-ticker.ds-activity-ticker [data-part='ticker-body'][data-part='ticker-body'] {
  border: 1px solid var(--ds-color-border-secondary);
}

/* current-item icon box — background + border + icon colour keyed on type ---- */

.ds-activity-ticker.ds-activity-ticker [data-part='item-icon-box'][data-type='success'] { background: var(--ds-color-success-100); color: var(--ds-color-success); }
.ds-activity-ticker.ds-activity-ticker [data-part='item-icon-box'][data-type='primary'] { background: var(--ds-color-primary-100); color: var(--ds-color-primary); }
.ds-activity-ticker.ds-activity-ticker [data-part='item-icon-box'][data-type='info']    { background: var(--ds-color-info-100);    color: var(--ds-color-info); }
