.ds-activity-cards.ds-activity-cards [data-part='accent-bar'][data-type='primary'] { background: linear-gradient(90deg, var(--ds-color-primary), var(--ds-color-primary-200)); }
.ds-activity-cards.ds-activity-cards [data-part='accent-bar'][data-type='info']    { background: linear-gradient(90deg, var(--ds-color-info), var(--ds-color-info-200)); }
.ds-activity-cards.ds-activity-cards [data-part='accent-bar'][data-type='warning'] { background: linear-gradient(90deg, var(--ds-color-warning), var(--ds-color-warning-200)); }
.ds-activity-cards.ds-activity-cards [data-part='accent-bar'][data-type='error']   { background: linear-gradient(90deg, var(--ds-color-error), var(--ds-color-error-200)); }

