.ds-activity-cards.ds-activity-cards [data-part='item-icon-box'][data-part='item-icon-box'][data-type='primary'] { border: 1px solid var(--ds-color-primary-200); }
.ds-activity-cards.ds-activity-cards [data-part='item-icon-box'][data-part='item-icon-box'][data-type='info']    { border: 1px solid var(--ds-color-info-200); }
.ds-activity-cards.ds-activity-cards [data-part='item-icon-box'][data-part='item-icon-box'][data-type='warning'] { border: 1px solid var(--ds-color-warning-200); }
.ds-activity-cards.ds-activity-cards [data-part='item-icon-box'][data-part='item-icon-box'][data-type='error']   { border: 1px solid var(--ds-color-error-200); }

