.ds-activity-cards.ds-activity-cards [data-part='item-dot'][data-type='success'] { background: var(--ds-color-success); }
.ds-activity-cards.ds-activity-cards [data-part='item-dot'][data-type='primary'] { background: var(--ds-color-primary); }
.ds-activity-cards.ds-activity-cards [data-part='item-dot'][data-type='info']    { background: var(--ds-color-info); }
