.ds-activity-cards.ds-activity-cards [data-part='item'][data-type='primary'] [data-part='item-row'] > svg { color: var(--ds-color-primary); }
.ds-activity-cards.ds-activity-cards [data-part='item'][data-type='info']    [data-part='item-row'] > svg { color: var(--ds-color-info); }
.ds-activity-cards.ds-activity-cards [data-part='item'][data-type='warning'] [data-part='item-row'] > svg { color: var(--ds-color-warning); }
.ds-activity-cards.ds-activity-cards [data-part='item'][data-type='error']   [data-part='item-row'] > svg { color: var(--ds-color-error); }

