.ds-metrics-minimal.ds-metrics-minimal [data-part='live-dot'] {
  border-radius: 50%;
  background: var(--ds-signal-card-badge-color, var(--ds-color-success));
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='live-label'][data-part='live-label'][data-part='live-label'] {
  color: var(--ds-signal-card-badge-color, var(--ds-color-success));
}

/* per-row shell ------------------------------------------------------------- */

.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'] {
  background: var(--ds-metric-card-bg, var(--ds-compact-card-bg, var(--ds-premium-card-bg, var(--ds-color-bg-primary))));
  border-radius: var(--ds-metric-card-radius, var(--ds-compact-card-radius, var(--ds-radius-md, 8px)));
  box-shadow: var(--ds-metric-card-shadow, var(--ds-compact-card-shadow, none));
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'][data-part='metric-row'] {
