}

/* accent bar — success/error meter fill by trend, hover widens 3px -> 4px ---- */

.ds-metrics-minimal.ds-metrics-minimal [data-part='accent-bar'] {
  width: 3px;
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row']:hover [data-part='accent-bar'] {
  width: 4px;
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'][data-positive='true'] [data-part='accent-bar'] {
  background: var(--ds-metric-card-meter-fill-success, var(--ds-metric-card-meter-fill, linear-gradient(90deg, var(--ds-color-primary), var(--ds-color-success))));
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'][data-positive='false'] [data-part='accent-bar'] {
  background: var(--ds-metric-card-meter-fill-error, linear-gradient(90deg, var(--ds-color-warning), var(--ds-color-error)));
}

/* row icon box — static bg/border, 3-tone icon colour, hover scale ---------- */

.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-icon-box'] {
  background: var(--ds-metric-card-icon-bg, var(--ds-signal-card-icon-bg, var(--ds-color-primary-100)));
  transform: scale(1);
