.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row']:hover [data-part='metric-icon-box'] {
  transform: scale(1.05);
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-icon-box'][data-part='metric-icon-box'] {
  border: 1px solid var(--ds-metric-card-icon-border, var(--ds-signal-card-icon-border, var(--ds-color-primary-200)));
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'][data-positive='true'] [data-part='metric-icon'] {
  color: var(--ds-metric-card-trend-color, var(--ds-color-success));
}
.ds-metrics-minimal.ds-metrics-minimal [data-part='metric-row'][data-positive='false'] [data-part='metric-icon'] {
  color: var(--ds-metric-card-trend-color-warning, var(--ds-color-warning));
