.ds-structure.ds-saved-views-menu[data-part='trigger'] {
  border-radius: 12px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-surface-card) 92%, white 8%), color-mix(in srgb, var(--ds-surface-card) 88%, var(--ds-color-bg-primary) 12%));
