}

.ds-structure.ds-saved-views-menu[data-part='trigger'][data-open='true'] {
  background: linear-gradient(180deg, color-mix(in srgb, var(--ds-color-primary) 12%, var(--ds-surface-card)), color-mix(in srgb, var(--ds-color-primary) 8%, var(--ds-surface-card)));
}

.ds-structure.ds-saved-views-menu[data-part='trigger'][data-part='trigger'][data-open='true'] {
  border-color: color-mix(in srgb, var(--ds-color-primary) 34%, transparent);
}

.ds-structure.ds-saved-views-menu [data-part='trigger-icon'] {
  border-radius: 10px;
