  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.rottay-transition-root[data-compact="true"] .rottay-transition-mark,
.rottay-transition-root[data-compact="true"] .rottay-transition-provider-icon {
