.rottay-transition-flow-tag {
  justify-self: center;
  color: var(--rh-ink);
}

.rottay-transition-flow-rail {
  position: relative;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--rh-line-strong), transparent);
  overflow: hidden;
}

.rottay-transition-flow-rail i {
  position: absolute;
