.ds-pattern-tenant-preview.ds-engine-rustic
  div:has(> [data-part="sample-card"])
  > div:first-child,
.ds-pattern-tenant-preview.ds-engine-rustic
  div:has(> [data-part="sample-input"])
  > div:first-child,
.ds-pattern-tenant-preview.ds-engine-rustic
  div:has(> div > [data-part="badge"])
  > div:first-child,
.ds-pattern-tenant-preview.ds-engine-rustic
  div:has(> [data-part="sample-table"])
