/* Animations (unlayered) */
/**
 * Animation Tokens Index - Rottay Design System
 *
 * Central import file for all animation-related tokens.
 * Includes transitions and keyframe animations.
 */

/**
 * Transition Tokens - Rottay Design System
 *
 * Transition timing and easing functions for smooth animations.
 * Provides consistent motion across the design system.
 */

:root {
  /* ========================================================================
     DURATION - Transition Speeds
     Standard durations for different types of animations
     ======================================================================== */
  --duration-instant: 0s;
  --duration-fastest: 0.1s;      /* 100ms - Micro-interactions */
  --duration-faster: 0.15s;      /* 150ms - Quick feedback */
  --duration-fast: 0.2s;         /* 200ms - Standard transitions */
  --duration-normal: 0.3s;       /* 300ms - Default duration */
  --duration-slow: 0.4s;         /* 400ms - Deliberate transitions */
  --duration-slower: 0.5s;       /* 500ms - Emphasized animations */
  --duration-slowest: 0.6s;      /* 600ms - Complex animations */
  --duration-glacial: 1s;        /* 1000ms - Very slow, special cases */

  /* Semantic durations */
  --duration-default: var(--duration-normal);
  --duration-quick: var(--duration-fast);
  --duration-emphasized: var(--duration-slow);

  /* ========================================================================
     EASING - Timing Functions
     Cubic bezier curves for natural motion
     ======================================================================== */

  /* Linear - No acceleration */
  --easing-linear: linear;

  /* Standard CSS easings */
  --easing-ease: ease;
  --easing-ease-in: ease-in;
  --easing-ease-out: ease-out;
  --easing-ease-in-out: ease-in-out;

  /* Custom ease-out (most common) */
  --easing-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --easing-emphasized: cubic-bezier(0.0, 0, 0.2, 1);
  --easing-decelerated: cubic-bezier(0.0, 0, 0.2, 1);

  /* Custom ease-in */
  --easing-accelerated: cubic-bezier(0.4, 0, 1, 1);

  /* Custom ease-in-out */
  --easing-standard-productive: cubic-bezier(0.2, 0, 0.38, 0.9);
  --easing-standard-expressive: cubic-bezier(0.4, 0.14, 0.3, 1);

  /* Sharp - Quick entrance/exit */
  --easing-sharp: cubic-bezier(0.4, 0, 0.6, 1);

  /* Bounce - Playful effect */
  --easing-bounce: cubic-bezier(0.68, -0.55, 0.265, 1.55);
  --easing-bounce-in: cubic-bezier(0.6, -0.28, 0.735, 0.045);
  --easing-bounce-out: cubic-bezier(0.175, 0.885, 0.32, 1.275);

  /* Overshoot - Slight overshoot for emphasis */
  --easing-overshoot: cubic-bezier(0.34, 1.56, 0.64, 1);

  /* Anticipate - Anticipation before action */
  --easing-anticipate: cubic-bezier(0.36, 0, 0.66, -0.56);

  /* Material Design easings */
  --easing-material-standard: cubic-bezier(0.4, 0.0, 0.2, 1);
  --easing-material-decelerate: cubic-bezier(0.0, 0.0, 0.2, 1);
  --easing-material-accelerate: cubic-bezier(0.4, 0.0, 1, 1);

  /* ========================================================================
     MOTION CANON (--ds-motion-*) — Quiet Premium
     The single motion contract every modern-engine component references, with
     ZERO literal fallbacks. Spec: engines/modern/README.md section 2. Defined
     at the foundation (NOT under [data-tenant]) so it can never silently vanish
     when the tenant attribute is absent. The legacy duration/easing tokens and
     the shared transition catalog below are left intact for the classic and
     rustic engines (zero visual delta).
     ======================================================================== */

  /* Durations — the 120/200/320ms product-law cadence. */
  --ds-motion-instant: 80ms;
  --ds-motion-fast: 120ms;
  --ds-motion-normal: 200ms;
  --ds-motion-slow: 320ms;
  --ds-motion-glacial: 500ms;

  /* Easings. ease-out is the premium curve (formerly copy-pasted as a literal). */
  --ds-motion-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ds-motion-ease-in-out: cubic-bezier(0.4, 0, 0.6, 1);
  /* Fallback only: a tenant BrandTheme with spring physics (springTension +
     springFriction, useSpring !== false) overrides these with a generated
     `linear()` curve scoped to its own [data-tenant] selector (see
     compilers/brand-theme's setMotionVariables / brandThemeToTokenOverrides).
     A tenant that declares no spring keeps this cubic-bezier approximation. */
  --ds-motion-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ds-motion-spring-gentle: cubic-bezier(0.25, 1.25, 0.5, 1);

  /* Entrance geometry — the start offsets a reveal animates FROM (paired with the durations). */
  --ds-motion-scale-in: 0.98;
  --ds-motion-offset-in: -2px;

  /* Pre-composed per-component transitions, re-expressed on the canon primitives.
     These are the ONLY thing modern components reference for multi-property
     transitions (no inline literals). */
  --ds-transition-button: background-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    color var(--ds-motion-fast) var(--ds-motion-ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out),
    transform var(--ds-motion-fast) var(--ds-motion-ease-out);
  --ds-transition-input: border-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out);
  --ds-transition-card: transform var(--ds-motion-normal) var(--ds-motion-ease-out),
    box-shadow var(--ds-motion-normal) var(--ds-motion-ease-out);
  --ds-transition-surface: background-color var(--ds-motion-normal) var(--ds-motion-ease-out),
    color var(--ds-motion-normal) var(--ds-motion-ease-out);
  --ds-transition-overlay: opacity var(--ds-motion-normal) var(--ds-motion-ease-out),
    transform var(--ds-motion-normal) var(--ds-motion-ease-out);
  --ds-transition-fade: opacity var(--ds-motion-normal) var(--ds-motion-ease-out);
  --ds-transition-color: color var(--ds-motion-fast) var(--ds-motion-ease-out),
    background-color var(--ds-motion-fast) var(--ds-motion-ease-out),
    border-color var(--ds-motion-fast) var(--ds-motion-ease-out);

  /* ========================================================================
     PROPERTY-SPECIFIC TRANSITIONS
     Pre-composed transitions for common properties
     ======================================================================== */

  /* All properties */
  --transition-all: all var(--duration-normal) var(--easing-standard);
  --transition-all-fast: all var(--duration-fast) var(--easing-standard);
  --transition-all-slow: all var(--duration-slow) var(--easing-standard);

  /* Opacity */
  --transition-opacity: opacity var(--duration-fast) var(--easing-standard);
  --transition-opacity-slow: opacity var(--duration-normal) var(--easing-standard);

  /* Transform */
  --transition-transform: transform var(--duration-normal) var(--easing-standard);
  --transition-transform-fast: transform var(--duration-fast) var(--easing-standard);
  --transition-transform-bounce: transform var(--duration-normal) var(--easing-bounce-out);

  /* Colors */
  --transition-color: color var(--duration-fast) var(--easing-standard);
  --transition-background: background-color var(--duration-fast) var(--easing-standard);
  --transition-border: border-color var(--duration-fast) var(--easing-standard);

  /* Box shadow */
  --transition-shadow: box-shadow var(--duration-normal) var(--easing-standard);
  --transition-shadow-fast: box-shadow var(--duration-fast) var(--easing-standard);

  /* Width/Height */
  --transition-width: width var(--duration-normal) var(--easing-standard);
  --transition-height: height var(--duration-normal) var(--easing-standard);
  --transition-size: width var(--duration-normal) var(--easing-standard),
                     height var(--duration-normal) var(--easing-standard);

  /* Margin/Padding */
  --transition-spacing: margin var(--duration-normal) var(--easing-standard),
                        padding var(--duration-normal) var(--easing-standard);

  /* Border radius */
  --transition-radius: border-radius var(--duration-normal) var(--easing-standard);

  /* ========================================================================
     COMPOSITE TRANSITIONS
     Combinations for common animation patterns
     ======================================================================== */

  /* Fade */
  --transition-fade: opacity var(--duration-normal) var(--easing-standard);
  --transition-fade-in: opacity var(--duration-normal) var(--easing-decelerated);
  --transition-fade-out: opacity var(--duration-fast) var(--easing-accelerated);

  /* Scale */
  --transition-scale: transform var(--duration-normal) var(--easing-standard);
  --transition-scale-up: transform var(--duration-normal) var(--easing-decelerated);
  --transition-scale-down: transform var(--duration-fast) var(--easing-accelerated);

  /* Slide */
  --transition-slide: transform var(--duration-normal) var(--easing-emphasized);

  /* Expand/Collapse */
  --transition-expand: height var(--duration-normal) var(--easing-emphasized),
                       opacity var(--duration-normal) var(--easing-standard);

  /* Fade + Scale (common for modals, popovers) */
  --transition-fade-scale: opacity var(--duration-normal) var(--easing-standard),
                           transform var(--duration-normal) var(--easing-standard);

  /* Fade + Slide */
  --transition-fade-slide: opacity var(--duration-normal) var(--easing-standard),
                           transform var(--duration-normal) var(--easing-emphasized);

  /* Color change */
  --transition-color-change: color var(--duration-fast) var(--easing-standard),
                             background-color var(--duration-fast) var(--easing-standard),
                             border-color var(--duration-fast) var(--easing-standard);

  /* ========================================================================
     COMPONENT-SPECIFIC TRANSITIONS
     Transitions optimized for specific components
     ======================================================================== */

  /* Button */
  --transition-button: background-color var(--duration-fast) var(--easing-standard),
                       color var(--duration-fast) var(--easing-standard),
                       border-color var(--duration-fast) var(--easing-standard),
                       box-shadow var(--duration-fast) var(--easing-standard),
                       transform var(--duration-fastest) var(--easing-standard);

  /* Input */
  --transition-input: border-color var(--duration-fast) var(--easing-standard),
                      box-shadow var(--duration-fast) var(--easing-standard);

  /* Card */
  --transition-card: transform var(--duration-normal) var(--easing-standard),
                     box-shadow var(--duration-normal) var(--easing-standard);

  /* Modal overlay */
  --transition-modal-overlay: opacity var(--duration-normal) var(--easing-standard);

  /* Modal content */
  --transition-modal-content: opacity var(--duration-normal) var(--easing-standard),
                              transform var(--duration-normal) var(--easing-emphasized);

  /* Dropdown */
  --transition-dropdown: opacity var(--duration-fast) var(--easing-decelerated),
                         transform var(--duration-fast) var(--easing-decelerated);

  /* Tooltip */
  --transition-tooltip: opacity var(--duration-faster) var(--easing-standard);

  /* Drawer */
  --transition-drawer: transform var(--duration-normal) var(--easing-emphasized);

  /* Toast/Notification */
  --transition-toast: opacity var(--duration-normal) var(--easing-standard),
                      transform var(--duration-normal) var(--easing-emphasized);

  /* Accordion */
  --transition-accordion: height var(--duration-normal) var(--easing-emphasized),
                          opacity var(--duration-fast) var(--easing-standard);

  /* Tab */
  --transition-tab: color var(--duration-fast) var(--easing-standard),
                    border-color var(--duration-fast) var(--easing-standard);

  /* Avatar */
  --transition-avatar: transform var(--duration-fast) var(--easing-standard),
                       box-shadow var(--duration-fast) var(--easing-standard);

  /* Switch/Toggle */
  --transition-switch: transform var(--duration-fast) var(--easing-standard),
                       background-color var(--duration-fast) var(--easing-standard);

  /* Progress bar */
  --transition-progress: width var(--duration-slower) var(--easing-standard);

  /* Skeleton loader */
  --transition-skeleton: opacity var(--duration-slow) var(--easing-standard);

  /* ========================================================================
     DELAY VALUES
     Stagger delays for sequential animations
     ======================================================================== */
  --delay-none: 0s;
  --delay-xs: 0.05s;       /* 50ms */
  --delay-sm: 0.1s;        /* 100ms */
  --delay-md: 0.15s;       /* 150ms */
  --delay-lg: 0.2s;        /* 200ms */
  --delay-xl: 0.3s;        /* 300ms */

  /* Stagger increments for lists */
  --delay-stagger-increment: 0.05s; /* 50ms between items */
}

/* ========================================================================
   REDUCED MOTION
   Respect user's motion preferences
   ======================================================================== */
@media (prefers-reduced-motion: reduce) {
  :root {
    /* Minimal durations */
    --duration-instant: 0s;
    --duration-fastest: 0.01s;
    --duration-faster: 0.01s;
    --duration-fast: 0.01s;
    --duration-normal: 0.01s;
    --duration-slow: 0.01s;
    --duration-slower: 0.01s;
    --duration-slowest: 0.01s;

    /* Linear easing only */
    --easing-standard: linear;
    --easing-emphasized: linear;
    --easing-bounce: linear;

    /* Disable delays */
    --delay-xs: 0s;
    --delay-sm: 0s;
    --delay-md: 0s;
    --delay-lg: 0s;
    --delay-xl: 0s;
    --delay-stagger-increment: 0s;
  }
}

/* =========================================================================
   DS-prefixed aliases for component consumption
   Components should use these --ds-* tokens, not the unprefixed versions.
   ========================================================================= */

:root {
  /* Duration aliases */
  --ds-duration-instant: var(--duration-instant, 0s);
  --ds-duration-fast: var(--duration-faster, 0.15s);
  --ds-duration-normal: var(--duration-fast, 0.2s);
  --ds-duration-slow: var(--duration-normal, 0.3s);
  --ds-duration-gentle: var(--duration-slow, 0.4s);

  /* Easing aliases */
  --ds-ease-out: var(--ds-ease-premium, cubic-bezier(0.16, 1, 0.3, 1));
  --ds-ease-in-out: var(--easing-standard, cubic-bezier(0.4, 0, 0.2, 1));

  /* Reduced motion override */
  --ds-motion-reduce: 0;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --ds-duration-instant: 0s;
    --ds-duration-fast: 0s;
    --ds-duration-normal: 0s;
    --ds-duration-slow: 0s;
    --ds-duration-gentle: 0s;
    --ds-motion-reduce: 1;
  }
}

/* =========================================================================
   VIEW TRANSITIONS + SCROLL-DRIVEN REVEAL
   Page-to-page transitions (View Transitions API) and CSS scroll-driven
   reveal, both expressed on the --ds-motion-* canon. The View Transitions
   root animation reuses --ds-page-transition-duration (defined in
   components/patterns.css as --ds-motion-normal) so page cadence stays in one
   place. Elements opt into the scroll reveal with the .ds-scroll-reveal class
   (see the ScrollReveal primitive). Both degrade to a static paint under
   reduced motion via the guarded block below.
   ========================================================================= */

@keyframes ds-view-transition-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes ds-view-transition-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

::view-transition-old(root) {
  animation: ds-view-transition-fade-out
    var(--ds-page-transition-duration, var(--ds-motion-normal))
    var(--ds-motion-ease-out) both;
}

::view-transition-new(root) {
  animation: ds-view-transition-fade-in
    var(--ds-page-transition-duration, var(--ds-motion-normal))
    var(--ds-motion-ease-out) both;
}

@keyframes ds-scroll-reveal-in {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Opt-in scroll-driven reveal. Active only where an animation can bind to the
   view() timeline; the ScrollReveal primitive uses an IntersectionObserver
   path otherwise. `animation-range` completes the reveal inside the entry
   phase and `both` holds the end state, so content reveals once as it scrolls
   into view and does not reverse on scroll-out. The duration is inert while a
   scroll timeline drives progress but is kept on the --ds-motion canon. */
@supports (animation-timeline: view()) {
  .ds-scroll-reveal {
    animation: ds-scroll-reveal-in var(--ds-motion-slow) var(--ds-motion-ease-out) both;
    animation-timeline: view();
    animation-range: entry 0% entry 60%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-scroll-reveal {
    animation: none;
    animation-timeline: auto;
    opacity: 1;
  }

  /* `*` matches every view-transition-name: "root" and every DS-assigned
     name (ds-vt-list-body, ds-vt-detail-body, ds-vt-record-<key>) alike, so
     a reduced-motion preference neutralizes the root crossfade and any
     element morph the same way. The group pseudo-element animates the
     transform/size interpolation between old and new geometry (the morph
     itself); old/new animate the opacity crossfade of their content.
     Without an animation, the group renders directly at the new geometry:
     an instant cut instead of motion. */
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none;
  }
}

/* =========================================================================
   DATA-CHANGED PULSE (.ds-pulse-changed)
   A single, non-looping flash for live-updating cells/rows (data-table live
   cells, live-feed rows). Uses an inset box-shadow rather than
   background-color so it layers on top of whatever background the element
   already has (striped rows, hover state, selection) instead of overwriting
   it. Intensity is tunable via --ds-effect-intensity (0 collapses the flash
   to fully transparent, satisfying a zero-decoration tenant without a
   separate opt-out). `animation` with no explicit iteration-count defaults
   to 1 -- this must NEVER be changed to `infinite` or given a `-loop`
   variant; the "one subtle flash" contract depends on it staying singular.
   Pair with the `usePulseOnChange` hook (patterns/foundation/hooks), which
   remounts the flashing node on each change so the animation restarts.
   ========================================================================= */
@keyframes ds-pulse-changed-flash {
  from {
    box-shadow: inset 0 0 0 9999px rgba(var(--ds-color-primary-rgb), calc(0.14 * var(--ds-effect-intensity, 1)));
  }
  to {
    box-shadow: inset 0 0 0 9999px rgba(var(--ds-color-primary-rgb), 0);
  }
}

.ds-pulse-changed {
  animation-name: ds-pulse-changed-flash;
  animation-duration: var(--ds-motion-slow);
  animation-timing-function: var(--ds-motion-ease-out);
}

@media (prefers-reduced-motion: reduce) {
  .ds-pulse-changed {
    animation: none;
  }
}

/**
 * Keyframe Animations - Rottay Design System
 *
 * CSS @keyframes definitions for reusable animations.
 * Use with animation property or combine with transition tokens.
 */

/* ========================================================================
   FADE ANIMATIONS
   Opacity-based entrance and exit animations
   ======================================================================== */

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(1rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in-down {
  from {
    opacity: 0;
    transform: translateY(-1rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in-left {
  from {
    opacity: 0;
    transform: translateX(-1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fade-in-right {
  from {
    opacity: 0;
    transform: translateX(1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* ========================================================================
   SCALE ANIMATIONS
   Grow and shrink effects
   ======================================================================== */

@keyframes scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes scale-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

@keyframes scale-up {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}

@keyframes scale-down {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(0);
  }
}

@keyframes zoom-in {
  from {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes zoom-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: scale(0.3);
  }
}

/* ========================================================================
   SLIDE ANIMATIONS
   Directional sliding effects
   ======================================================================== */

@keyframes slide-in-up {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes slide-in-down {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes slide-in-left {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes slide-in-right {
  from {
    transform: translateX(100%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes slide-out-up {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(-100%);
  }
}

@keyframes slide-out-down {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(100%);
  }
}

@keyframes slide-out-left {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-100%);
  }
}

@keyframes slide-out-right {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(100%);
  }
}

/* ========================================================================
   ROTATE ANIMATIONS
   Spinning and rotation effects
   ======================================================================== */

@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes spin-reverse {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes rotate-in {
  from {
    opacity: 0;
    transform: rotate(-180deg);
  }
  to {
    opacity: 1;
    transform: rotate(0deg);
  }
}

@keyframes rotate-out {
  from {
    opacity: 1;
    transform: rotate(0deg);
  }
  to {
    opacity: 0;
    transform: rotate(180deg);
  }
}

/* ========================================================================
   BOUNCE ANIMATIONS
   Playful bouncing effects
   ======================================================================== */

@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-25%);
  }
}

@keyframes bounce-in {
  0% {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
    transform: scale(1.05);
  }
  70% {
    transform: scale(0.9);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes bounce-out {
  0% {
    transform: scale(1);
  }
  25% {
    transform: scale(0.95);
  }
  50% {
    opacity: 1;
    transform: scale(1.1);
  }
  100% {
    opacity: 0;
    transform: scale(0.3);
  }
}

/* ========================================================================
   SHAKE ANIMATIONS
   Error indication and attention grabbers
   ======================================================================== */

@keyframes shake {
  0%, 100% {
    transform: translateX(0);
  }
  10%, 30%, 50%, 70%, 90% {
    transform: translateX(-0.5rem);
  }
  20%, 40%, 60%, 80% {
    transform: translateX(0.5rem);
  }
}

@keyframes shake-vertical {
  0%, 100% {
    transform: translateY(0);
  }
  10%, 30%, 50%, 70%, 90% {
    transform: translateY(-0.5rem);
  }
  20%, 40%, 60%, 80% {
    transform: translateY(0.5rem);
  }
}

/* ========================================================================
   PULSE ANIMATIONS
   Attention and loading indicators
   ======================================================================== */

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@keyframes pulse-scale {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  100% {
    transform: scale(1.5);
    opacity: 0;
  }
}

/* ========================================================================
   SHIMMER/LOADING ANIMATIONS
   Skeleton loaders and loading states
   ======================================================================== */

@keyframes shimmer {
  0% {
    background-position: -100% 0;
  }
  100% {
    background-position: 100% 0;
  }
}

@keyframes skeleton-loading {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

@keyframes progress-indeterminate {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

/* ========================================================================
   FLIP ANIMATIONS
   Card flip and rotation effects
   ======================================================================== */

@keyframes flip-horizontal {
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(180deg);
  }
}

@keyframes flip-vertical {
  0% {
    transform: rotateX(0deg);
  }
  100% {
    transform: rotateX(180deg);
  }
}

/* ========================================================================
   SWING ANIMATIONS
   Pendulum and hanging effects
   ======================================================================== */

@keyframes swing {
  0%, 100% {
    transform: rotate(0deg);
  }
  20% {
    transform: rotate(15deg);
  }
  40% {
    transform: rotate(-10deg);
  }
  60% {
    transform: rotate(5deg);
  }
  80% {
    transform: rotate(-5deg);
  }
}

/* ========================================================================
   WIGGLE ANIMATIONS
   Playful attention grabbers
   ======================================================================== */

@keyframes wiggle {
  0%, 100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(-5deg);
  }
  75% {
    transform: rotate(5deg);
  }
}

/* ========================================================================
   HEARTBEAT ANIMATION
   Like/favorite indication
   ======================================================================== */

@keyframes heartbeat {
  0%, 100% {
    transform: scale(1);
  }
  14% {
    transform: scale(1.3);
  }
  28% {
    transform: scale(1);
  }
  42% {
    transform: scale(1.3);
  }
  56% {
    transform: scale(1);
  }
}

/* ========================================================================
   BLINK ANIMATION
   Cursor and attention indication
   ======================================================================== */

@keyframes blink {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* ========================================================================
   TYPING DOTS ANIMATION
   Loading indicator with dots
   ======================================================================== */

@keyframes typing-dots {
  0%, 60%, 100% {
    transform: translateY(0);
  }
  30% {
    transform: translateY(-0.5rem);
  }
}

/* ========================================================================
   RIPPLE ANIMATION
   Material-style ripple effect
   ======================================================================== */

@keyframes ripple {
  0% {
    transform: scale(0);
    opacity: 1;
  }
  100% {
    transform: scale(4);
    opacity: 0;
  }
}

/* ========================================================================
   GLOW ANIMATION
   Glowing effect for emphasis
   ======================================================================== */

@keyframes glow {
  0%, 100% {
    box-shadow: 0 0 0.5rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.5);
  }
  50% {
    box-shadow: 0 0 1.5rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.8),
                0 0 2rem rgba(var(--ds-color-primary-rgb, 0, 102, 204), 0.4);
  }
}

/* ========================================================================
   COMPONENT-SPECIFIC ANIMATIONS
   Keyframes used by individual DS components
   ======================================================================== */

/* Button spinner - used by Rustic and Modern engines */
@keyframes rottay-button-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* Button pulse - used by Rustic engine */
@keyframes rottay-button-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(var(--ds-color-primary-rgb, 59, 130, 246), 0.5);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(var(--ds-color-primary-rgb, 59, 130, 246), 0);
  }
}

/* Modal entrance - used by Modern engine */
@keyframes rottay-modal-enter {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Modal backdrop entrance - used by Modern engine */
@keyframes rottay-modal-backdrop-enter {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Select dropdown slide-in - used by Modern engine */
@keyframes rottay-select-slide-in {
  from {
    opacity: 0;
    transform: scaleY(0.95);
    transform-origin: top;
  }
  to {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: top;
  }
}

/* Tabs panel fade-in - used by Modern engine */
@keyframes rottay-tabs-fade-in {
  from {
    opacity: 0;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ========================================================================
   MODAL & OVERLAY ANIMATIONS
   Shared keyframes for modal entrance and backdrop fade.
   ======================================================================== */

@keyframes ds-modal-enter {
  from { opacity: 0; transform: scale(0.95) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes ds-backdrop-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

/**
 * Premium Effect Tokens - Rottay Design System
 *
 * The gradient / glass / glow layer for the modern engine's Quiet Premium
 * signature. Every effect below is scaled by --ds-effect-intensity so a tenant
 * collapses the whole layer to flat by setting the dial to 0 (BitHire's
 * Evidence-Ledger zero-decoration law); the DS/rottay default (1) showcases the
 * full treatment.
 *
 * Sanctioned roles (engines/modern spec section 5):
 *   surface-tint  --ds-gradient-surface  -> cards, hero surfaces, metric tiles
 *   accent        --ds-gradient-primary  -> primary buttons, selected states
 *   signal-glow   --ds-shadow-glow-*     -> live/AI moments + data-viz ONLY
 *   glass         --ds-glass-*           -> overlay backdrops ONLY (modal/palette/drawer)
 *   mesh          --ds-gradient-mesh     -> marketing/showcase ONLY (never product chrome)
 */

:root {
  /* ========================================================================
     EFFECT INTENSITY DIAL
     Tenant/vertical-tunable multiplier. 1 = full Quiet Premium (DS/rottay
     default); 0 = flat (no gradient/glass/glow). Every effect multiplies its
     alpha/length by this, so intensity 0 collapses each effect to none while
     keeping valid CSS (blur(0px), transparent stops, 0-alpha shadow).
     Emitted per tenant by compilers/brand-theme from surfaces.effectIntensity.
     ======================================================================== */
  --ds-effect-intensity: 1;

  /* ========================================================================
     GLASSMORPHISM (overlay backdrops ONLY: modal, command palette, drawer)
     Base palette tokens are read by the glass-card effect and exposed through
     the useTokens() catalog; blur/bg/border scale with --ds-effect-intensity so
     a zero-intensity tenant (bithire) collapses them without needing a per-token
     'none' override. The two composed backdrop tokens are the wired overlay
     values and likewise collapse to a plain scrim at intensity 0.
     ======================================================================== */
  --ds-glass-blur: calc(12px * var(--ds-effect-intensity));
  --ds-glass-blur-sm: 8px;
  --ds-glass-blur-lg: 20px;
  --ds-glass-blur-xl: 32px;
  --ds-glass-bg: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));
  --ds-glass-bg-light: var(--ds-color-alpha-white-10);
  --ds-glass-bg-heavy: var(--ds-color-alpha-white-20);
  --ds-glass-border: rgba(255, 255, 255, calc(0.10 * var(--ds-effect-intensity)));
  --ds-glass-border-light: var(--ds-color-alpha-white-5);
  --ds-glass-border-heavy: var(--ds-color-alpha-white-20);

  /* Wired overlay-backdrop values. Intensity 0 -> blur(0px) + transparent tint,
     i.e. the backdrop falls back to its plain scrim. The 12px/0.05 literals are
     inlined (not var(--ds-glass-blur)) so a tenant hard-nulling --ds-glass-blur
     cannot turn this into the invalid blur(none). */
  --ds-glass-backdrop-filter: blur(calc(12px * var(--ds-effect-intensity)));
  --ds-glass-scrim-tint: rgba(255, 255, 255, calc(0.05 * var(--ds-effect-intensity)));

  /* ========================================================================
     SIGNAL-GLOW (live/AI moments + data-viz emphasis ONLY, never static chrome)
     ======================================================================== */
  --ds-shadow-glow-primary: 0 0 calc(40px * var(--ds-effect-intensity)) rgba(var(--ds-color-primary-rgb), calc(0.18 * var(--ds-effect-intensity)));

  /* ========================================================================
     GRADIENTS
     ======================================================================== */
  /* surface-tint: barely-there ~2-3% vertical luminance tint that replaces flat
     fills on cards, hero surfaces and metric tiles. */
  --ds-gradient-surface: linear-gradient(
    180deg,
    rgba(255, 255, 255, calc(0.025 * var(--ds-effect-intensity))) 0%,
    rgba(255, 255, 255, calc(0.004 * var(--ds-effect-intensity))) 52%,
    rgba(0, 0, 0, calc(0.02 * var(--ds-effect-intensity))) 100%
  );
  /* accent: subtle top-light sheen on primary buttons and selected states. */
  --ds-gradient-primary: linear-gradient(
