  --ds-font-family-display: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;

  /* Letter Spacing */
  --ds-letter-spacing-display: -0.02em;
  --ds-letter-spacing-heading: -0.01em;
  --ds-letter-spacing-body: 0;
  --ds-letter-spacing-mono: 0;

  /* Line Heights */
  --ds-line-height-display: 1.1;
  --ds-line-height-heading: 1.25;
  --ds-line-height-body: 1.6;
  --ds-line-height-tight: 1.25;
  --ds-line-height-relaxed: 1.75;

  /* Border Radius - same as light (shape doesn't change with theme) */
  --ds-radius-sm: 6px;
  --ds-radius-md: 8px;
  --ds-radius-lg: 12px;
  --ds-radius-xl: 16px;
  --ds-radius-full: 9999px;

  /* Shadows - same authored scale as light (BrandTheme has one scale) */
  --ds-shadow-sm: 0 1px 2px rgba(22, 42, 67, 0.06);
  --ds-shadow-md: 0 4px 12px rgba(22, 42, 67, 0.08);
  --ds-shadow-lg: 0 8px 24px rgba(22, 42, 67, 0.1);
  --ds-shadow-xl: 0 16px 48px rgba(22, 42, 67, 0.12);

  /* Button overrides - dark */
  --ds-button-primary-bg: #1A7FE0;
  --ds-button-primary-bg-hover: #2B8FEF;
  --ds-button-primary-color: #FFFFFF;
  --ds-button-secondary-bg: transparent;
  --ds-button-secondary-border: #253545;
  --ds-button-secondary-color: #9AACBF;
  --ds-button-secondary-bg-hover: #1B2535;

  /* Card overrides - dark */
  --ds-card-bg: #151D2B;
  --ds-card-bg-hover: #1B2535;
  --ds-card-border: #253545;
  --ds-card-shadow: 0 4px 12px rgba(22, 42, 67, 0.16), 0 2px 4px rgba(22, 42, 67, 0.10);
  --ds-card-shadow-hover: 0 8px 24px rgba(22, 42, 67, 0.18), 0 4px 8px rgba(22, 42, 67, 0.12);

  /* Input overrides - dark */
  --ds-input-bg: #0F1520;
  --ds-input-border: #253545;
  --ds-input-border-hover: #3A4A5A;
  --ds-input-border-focus: #1A7FE0;
  --ds-input-shadow-focus: 0 0 0 1px #1A7FE0;
  --ds-input-color: #E4E8ED;
  --ds-input-color-placeholder: #5A7085;

  /* Table - dark */
  --ds-table-bg: #0F1520;
  --ds-table-border: #1D2A38;
  --ds-table-radius: var(--ds-radius-lg);
  --ds-table-header-bg: #151D2B;
