  /* Link colors - dark */
  --ds-color-link: #3B9AF0;
  --ds-color-link-hover: #6BB5F5;
  --ds-color-link-visited: #A78BCA;

  /* Interactive states - dark */
  --ds-color-interactive-border: #253545;
  --ds-color-interactive-bg-hover: rgba(255, 255, 255, 0.04);
  --ds-color-interactive-bg-active: rgba(26, 127, 224, 0.12);
  --ds-color-interactive-bg-muted: rgba(255, 255, 255, 0.03);

  /* Status colors - dark */
  --ds-color-success: #2D8A6E;
  --ds-color-success-50: #0A1F18;
  --ds-color-success-100: #0F2E24;
  --ds-color-success-bg: #0F2E24;
