  --ds-color-info-100: #112840;
  --ds-color-info-bg: #112840;
  --ds-color-info-border: rgba(26, 127, 224, 0.3);

  /* Accent for live indicators - dark */
  --ds-color-accent-live: #38A080;
  --ds-color-accent-live-bg: #0F2E24;

  /* ============================================
     SIDEBAR NAVIGATION - dark
     ============================================ */

  /* Group Headers */
  --ds-sidebar-group-font-size: 11px;
  --ds-sidebar-group-font-weight: 600;
  --ds-sidebar-group-color: #5A7085;
  --ds-sidebar-group-letter-spacing: 0.04em;
  --ds-sidebar-group-margin-top: 8px;
  --ds-sidebar-group-margin-bottom: 4px;
