  --ds-sidebar-icon-size: 16px;

  /* Sidebar specific */
  --ds-sidebar-bg: #0A0F18;
  --ds-sidebar-footer-bg: #0A0F18;
  --ds-sidebar-border: #1D2A38;
  --ds-sidebar-text: #9AACBF;
  --ds-sidebar-text-muted: #5A7085;

  /* ============================================
     BITHIRE SPECIFIC - Recruiting Domain Tokens (dark)
     ============================================ */

  /* Candidate Pipeline States */
  --ds-candidate-new: var(--ds-color-info-100);
  --ds-candidate-new-text: var(--ds-color-primary-700);
  --ds-candidate-screening: var(--ds-color-warning-100);
  --ds-candidate-screening-text: var(--ds-color-warning);
  --ds-candidate-interview: var(--ds-color-primary-100);
  --ds-candidate-interview-text: var(--ds-color-primary-700);
  --ds-candidate-offer: var(--ds-color-success-100);
  --ds-candidate-offer-text: var(--ds-color-success);
  --ds-candidate-hired: var(--ds-color-success-200);
  --ds-candidate-hired-text: var(--ds-color-secondary-800);
  --ds-candidate-rejected: var(--ds-color-error-100);
  --ds-candidate-rejected-text: var(--ds-color-error);

  /* Job States */
  --ds-job-draft: var(--ds-color-neutral-100);
  --ds-job-draft-text: var(--ds-color-neutral-600);
  --ds-job-open: var(--ds-color-success-100);
  --ds-job-open-text: var(--ds-color-success);
  --ds-job-closed: var(--ds-color-neutral-200);
  --ds-job-closed-text: var(--ds-color-neutral-500);
  --ds-job-paused: var(--ds-color-warning-100);
  --ds-job-paused-text: var(--ds-color-warning);

  /* Interview States */
  --ds-interview-scheduled: var(--ds-color-info-100);
  --ds-interview-scheduled-text: var(--ds-color-primary-700);
  --ds-interview-completed: var(--ds-color-success-100);
  --ds-interview-completed-text: var(--ds-color-success);
  --ds-interview-cancelled: var(--ds-color-error-100);
  --ds-interview-cancelled-text: var(--ds-color-error);
  --ds-interview-no-show: var(--ds-color-warning-100);
  --ds-interview-no-show-text: var(--ds-color-warning);
}

