/* ============================================================================
 * Evidence Ledger interaction layer (WO-DES-11 — design-language §8.1-§8.2)
 *
 * The Ledger's margin notes: ONE tag/badge system and ONE tooltip system,
 * driven by the closed tint scale (§2.5) and composite type ramp (§2.1) the
 * compiler emits above. Tags are pills at detail size, sentence case; tones
 * read bg = tint-8, text = tone color, border = tint-24 — never saturated
 * fills, white-on-color, or uppercase. Counting badges render tabular figures.
 * Tooltips are a calm level-2 paper overlay. Everything animates on the §2.6
 * motion tokens. Scoped to the tenant so it is theme-driven with zero product
 * semantics; plain (non-:where) selectors clear antd v5's :where()-wrapped
 * component styles without !important.
 * ============================================================================ */

:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag {
  border-radius: var(--ds-tag-radius-full, 9999px);
  font-size: var(--ds-text-detail-size, 0.75rem);
  font-weight: 600;
  line-height: 1.5;
  text-transform: none;
  letter-spacing: 0;
  border-width: 1px;
  border-style: solid;
  font-variant-numeric: tabular-nums;
  transition:
    background-color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease),
    border-color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease),
    color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease);
}

/* Six-tone vocabulary (S4): bg = tint-8 of the tone, text = the tone color,
 * border = tint-24 of the tone. Neutral/info fall back to the primary tint. */
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--default {
  background: var(--ds-tint-8);
  color: var(--ds-color-text-secondary, #52677E);
  border-color: var(--ds-tint-24);
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--primary,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-blue {
  background: var(--ds-tint-8);
  color: var(--ds-color-primary);
  border-color: var(--ds-tint-24);
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--success,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-success,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-green {
  background: var(--ds-tint-success-8);
  color: var(--ds-color-success);
  border-color: var(--ds-tint-success-24);
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--warning,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-warning,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-gold,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-orange {
  background: var(--ds-tint-warning-8);
  color: var(--ds-color-warning);
  border-color: var(--ds-tint-warning-24);
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--error,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-error,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-red {
  background: var(--ds-tint-error-8);
  color: var(--ds-color-error);
  border-color: var(--ds-tint-error-24);
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--secondary,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag-cyan {
  background: var(--ds-tint-info-8);
  color: var(--ds-color-info);
  border-color: var(--ds-tint-info-24);
}

/* Interactive tags (filters, removable skills) take the §2.5 interaction
 * states: tint-4 hover on top of the resting tone tint. */
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag[style*='cursor: pointer']:hover,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag--clickable:hover {
  filter: brightness(0.98);
}

/* Counting badges render tabular figures (§8.6); no saturated pulse. */
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-badge-count,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-scroll-number,
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-badge {
  font-variant-numeric: tabular-nums;
}

/* Tabular numerals everywhere data renders (§8.6 item 1; WO-DES-13). The display
 * and title composite tokens carry a `-numeric` facet (font-variant-numeric cannot
 * ride the `font` shorthand, so it is a companion like -letter-spacing), and DS
 * data-table cells align digit-for-digit by default so screens stop hand-setting
 * font-variant-numeric per cell — the property only affects digits, so covering the
 * whole table is safe for text columns. */
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) {
  --ds-text-display-numeric: tabular-nums;
  --ds-text-title-numeric: tabular-nums;
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) :where(.ds-pattern-data-table) :where(td, th) {
  font-variant-numeric: tabular-nums;
}

/* Tooltip — the calm level-2 paper overlay (§8.2): white surface, tint hairline,
 * radius-sm, detail-size ink text, ~280px max. Opacity-only enter at calm,
 * position never animates; exit is instant (antd hideDelay). */
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tooltip .ant-tooltip-inner {
  background: var(--ds-color-bg-primary, #FFFFFF);
  color: var(--ds-color-text-primary, #162A43);
  border: 1px solid var(--ds-tint-12);
  border-radius: var(--ds-radius-sm, 6px);
  box-shadow: var(--ds-shadow-lg);
  font-size: var(--ds-text-detail-size, 0.75rem);
  line-height: 1.4;
  max-width: var(--ds-tooltip-max-width, 280px);
  padding: 6px 10px;
}
:is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tooltip .ant-tooltip-arrow::before {
  background: var(--ds-color-bg-primary, #FFFFFF);
}

/* Reduced-motion law (§2.6/§8.1): everything collapses to opacity, durations
 * resolve to 0. Re-declare the motion tokens at tenant specificity (beats the
 * compiled block) so DS components reading var(--ds-motion-*) go instant, and
 * neutralize the tag transition authored above. */
@media (prefers-reduced-motion: reduce) {
  :is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) {
    --ds-motion-instant: 0ms;
    --ds-motion-calm: 0ms;
    --ds-motion-deliberate: 0ms;
  }
  :is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .rottay-tag,
  :is(html[data-tenant='bithire'], :where([data-ds-root][data-vertical='bithire'])) .ant-tag {
    transition: none;
  }
}

/* ============================================
   BITHIRE PRODUCTION GUARDRAILS (TOKEN REMAP)
   Relocated verbatim from app-bithire src/app/globals.css region UX05-R01
   (WO-UX-05 stage E). Plain tenant-root scope, appended after every other
   artifact block so these declarations win by source order over the compiled
   BrandTheme block above -- mirroring the app, where globals.css loaded after
   the artifact. The higher-specificity light/dark theme blocks earlier in
   this file keep their runtime winners for the var names they also declare,
   exactly as in production today (the app pins data-theme="light" for
   bithire, so the light block always applies and the dark blocks never do).
   Deliberate exception to the verbatim copy: the two legacy "-text"-suffixed
   button ink aliases (primary/secondary) are NOT relocated. The artifact
   gates ban that legacy suffix (engines consume the canonical
   --ds-button-*-color vars; the legacy fallback is unreachable while -color
   is declared), and app-bithire styles/foundation.css re-declares the same
   aliases with identical values at :root.
   ============================================ */
/*
 * BitHire production guardrails.
 *
 * The imported DS package still contains platform fallback literals for generic
 * tenants. Keep this app on semantic BitHire/DS tokens so controls stay
 * readable in production bundles and button/pill text cannot disappear against
 * light surfaces.
 */
:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) {
  --ds-control-ink: var(--ds-color-text-primary);
  --ds-control-ink-muted: var(--ds-color-text-secondary);
  --ds-control-on-brand: var(
    --ds-color-text-on-primary,
    var(--ds-color-text-inverse)
  );
  --ds-color-on-primary: var(--ds-control-on-brand);
  --ds-control-surface: var(--ds-surface-card);
  --ds-control-surface-raised: color-mix(
    in srgb,
    var(--ds-surface-card) 86%,
    var(--ds-surface-panel)
  );
  --ds-control-brand-tint: color-mix(
    in srgb,
    var(--ds-color-primary) 10%,
    var(--ds-control-surface)
  );
  --ds-control-brand-tint-hover: color-mix(
    in srgb,
    var(--ds-color-primary) 15%,
    var(--ds-control-surface)
  );
  --ds-control-brand-border: color-mix(
    in srgb,
    var(--ds-color-primary) 30%,
    var(--ds-color-border)
  );
  --ds-command-glow: 0 18px 46px
    color-mix(in srgb, var(--ds-color-primary) 8%, transparent);
  --ds-icon-tile-border: color-mix(
    in srgb,
    var(--ds-color-primary) 22%,
    var(--ds-color-border)
  );
  --ds-chip-bg: var(--ds-control-brand-tint);
  --ds-chip-color: var(--ds-color-primary);
  --ds-chip-border: var(--ds-control-brand-border);
  --ds-premium-card-border: color-mix(
    in srgb,
    var(--ds-color-primary) 12%,
    var(--ds-color-border)
  );
  --ds-premium-card-border-hover: color-mix(
    in srgb,
    var(--ds-color-primary) 28%,
    var(--ds-color-border)
  );
  --ds-premium-card-selected-border: color-mix(
    in srgb,
    var(--ds-color-primary) 46%,
    var(--ds-color-border)
  );
  --ds-premium-card-selected-ring: 0 0 0 3px
    color-mix(in srgb, var(--ds-color-primary) 12%, transparent);
  --ds-card-bg: var(--ds-surface-card);
  --ds-card-bg-hover: color-mix(
    in srgb,
    var(--ds-color-primary) 4%,
    var(--ds-surface-card)
  );
  --ds-card-border: var(--ds-premium-card-border);
  --ds-card-border-hover: var(--ds-premium-card-border-hover);
  --ds-card-border-color: var(--ds-premium-card-border);
  --ds-card-border-color-hover: var(--ds-premium-card-border-hover);
  --ds-card-radius: var(--ds-radius-md);
  --ds-card-border-radius: var(--ds-radius-md);
  --ds-card-shadow: var(--ds-surface-shadow, var(--ds-shadow-sm));
  --ds-card-shadow-hover: var(--ds-surface-shadow-hover, var(--ds-shadow-md));
  --ds-card-title-letter-spacing: 0;
  --ds-card-body-color: var(--ds-color-text-primary);
  --ds-card-footer-bg: var(--ds-premium-card-footer-bg);
  --ds-surface-card-bg: var(--ds-surface-card);
  --ds-surface-panel-bg: var(--ds-surface-panel);
  --ds-surface-card-border: var(--ds-color-border);
  --ds-surface-card-border-strong: var(--ds-color-border-secondary);
  --ds-surface-card-border-soft: var(--ds-color-border-subtle);
  --ds-surface-card-grid-size: 22px;
  --ds-surface-card-grid-line: color-mix(
    in srgb,
    var(
        --rt-premium-card-accent,
        var(--ds-signal-card-accent, var(--ds-color-primary))
      )
      5%,
    transparent
  );
  --ds-surface-card-grid-line-strong: color-mix(
    in srgb,
    var(
        --rt-premium-card-accent,
        var(--ds-signal-card-accent, var(--ds-color-primary))
      )
      8%,
    transparent
  );
  --ds-surface-card-grid-bg:
    linear-gradient(var(--ds-surface-card-grid-line) 1px, transparent 1px),
    linear-gradient(
      90deg,
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      115deg,
      transparent 0%,
      color-mix(in srgb, var(--ds-surface-card) 34%, transparent) 46%,
      transparent 66%
    );
  --rt-premium-card-grid:
    linear-gradient(var(--ds-surface-card-grid-line) 1px, transparent 1px),
    linear-gradient(
      90deg,
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    );
  --ds-card-top-line-display: none;
  --ds-card-top-line-height: 0px;
  --ds-card-top-line-bg: transparent;
  --ds-premium-card-header-top-line-display: none;
