:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire']))
  :where(.btn-primary, .ds-btn--primary, .ant-btn-primary) {
  color: var(--ds-button-primary-color);
  background: var(--ds-button-primary-bg);
  border-color: var(--ds-button-primary-border);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire']))
  :where(.btn-secondary, .ds-btn--secondary, .ant-btn-default) {
  color: var(--ds-button-secondary-color);
  background: var(--ds-button-secondary-bg);
  border-color: var(--ds-button-secondary-border);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire']))
  :where(.btn-ghost, .ds-btn--ghost, .ant-btn-text, .ant-btn-link) {
  color: var(--ds-button-ghost-color);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.btn-link, .ds-btn--link, .ant-btn-link) {
  color: var(--ds-button-link-color);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire']))
  :where(
    .badge-default,
    .ds-badge--default,
    .ds-badge:not(.ds-badge--primary):not(.ds-badge--secondary):not(
        .ds-badge--success
      ):not(.ds-badge--warning):not(.ds-badge--error):not(.ds-badge--info)
  ) {
  color: var(--ds-badge-default-color);
  background: var(--ds-badge-default-bg);
  border-color: var(--ds-badge-default-border);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.badge-primary, .ds-badge--primary) {
  color: var(--ds-badge-primary-color);
  background: var(--ds-badge-primary-bg);
  border-color: var(--ds-badge-primary-border);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.badge-secondary, .ds-badge--secondary) {
  color: var(--ds-badge-secondary-color);
  background: var(--ds-badge-secondary-bg);
  border-color: var(--ds-badge-secondary-border);
}

