  background: var(--ds-badge-error-bg);
  border-color: var(--ds-badge-error-border);
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.badge-info, .ds-badge--info) {
  color: var(--ds-badge-info-color);
