:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.badge, .ds-badge) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  min-height: var(--ds-badge-height, 28px);
  padding-block: 0.25rem;
  padding-inline: var(--ds-badge-padding-x, 0.625rem);
  overflow: hidden;
  border-width: 1px;
  border-style: solid;
  border-radius: var(--ds-badge-radius, var(--ds-radius-full, 999px));
  background-clip: padding-box;
  box-shadow: inset 0 1px 0
    color-mix(in srgb, var(--ds-control-surface) 68%, transparent);
  font-weight: var(--ds-badge-font-weight, 700);
  line-height: var(--ds-badge-line-height, 1.2);
  text-overflow: ellipsis;
  transform: none;
  transition:
    color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease),
    background-color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease),
    border-color var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease),
    box-shadow var(--ds-motion-instant, 120ms) var(--ds-ease-standard, ease);
  vertical-align: middle;
  white-space: nowrap;
}

:is(html[data-tenant="bithire"], :where([data-ds-root][data-vertical='bithire'])) :where(.badge > *, .ds-badge > *) {
